INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (1, N'Air Quality', N'air-quality', N'#9CC3EA', 10, N'Particulate matter, ozone, carbon monoxide, and visibility.', N'Achieve strictest of federal, state, or regional standards for carbon monoxide, ozone, and particulates; increase visibility; and reduce automobile traffic.', N'AirQuality');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (3, N'Recreation', N'recreation', N'#F78814', 20, N'Recreation capacity, access, and visitor experience.', N'Preserve and enhance a high-quality recreational experience. Preserve undeveloped shorezone and other natural areas and maintain a fair share of recreational capacity for the general public.', N'Recreation');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (4, N'Scenic Resources', N'scenic-resources', N'#B0A843', 30, N'Scenic quality along roadways, the shoreline, and public viewpoints.', N'Maintain or improve roadway and shoreline scenic travel route ratings, maintain or improve views of individual scenic resources, and maintain or improve quality of views from public outdoor recreation areas.', N'ScenicResources');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (5, N'Soil Conservation', N'soil-conservation', N'#9A5710', 40, N'Stream environment zones and land coverage.', N'Preserve natural SEZ, restore 25% of disturbed urban SEZ areas, and prevent soil compaction and land coverage that restricts infiltration through coverage limitations.', N'SoilConservation');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (7, N'Water Quality', N'water-quality', N'#0F3F6F', 50, N'Lake clarity, nearshore conditions, streams, and stormwater runoff.', N'Return the Lake to 1960s water clarity and algal levels by reducing nutrient and sediment in surface runoff and groundwater.', N'WaterQuality');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (9, N'Noise', N'noise', N'#675EA1', 60, N'Sound levels along highways, in plan areas, and on the shorezone.', N'Minimize noise disturbance from single events and minimize background noise disturbance in accordance with land use patterns.', N'Noise');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (10, N'Transportation and Sustainable Communities', N'transportation-and-sustainable-communities', N'#DB5B00', 70, N'Traffic, transit, bicycle and pedestrian counts, safety, and travel behavior.', N'Reduce dependence on the automobile, support GHG emission reduction, and increase mobility.', N'TransportationAndSustainableCommunities');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (11, N'Forest Structure', N'forest-structure', N'#415414', 80, N'Seral stage, canopy cover, and stand density of the conifer forest.', N'Restore a balanced mosaic of forest ages, from young trees to old growth, and of open and closed canopies, and keep stands at densities that leave forests less vulnerable to drought, insects, disease, and severe wildfire.', N'category-icons/ForestStructure-white-icon.svg');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (12, N'Fire Dynamics', N'fire-dynamics', N'#9C3E27', 90, N'Burn probability, likely fire severity, and area burned.', N'Keep fire behavior defensible around neighborhoods and evacuation routes, and limit the size and extent of large, high-severity fire patches across the forested landscape.', N'category-icons/FireDynamics-white-icon.svg');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (13, N'Biodiversity', N'biodiversity', N'#4A6118', 100, N'Sensitive and uncommon plants, native vegetation, fish, and special interest wildlife.', N'Maintain vegetation community richness and diversity, preserve uncommon plant communities and sustainable populations of sensitive plants, maintain and improve stream and lake fish habitat, and provide and protect suitable habitat for special interest species.', N'category-icons/Biodiversity-white-icon.svg');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (14, N'Demographics', N'demographics', N'#7c7c7c', 110, N'Population, age, race and ethnicity, housing, and income of the Tahoe Region.', N'Describe who lives in the Tahoe Region and how that is changing, from census counts and estimates, to inform housing, transportation, and community planning.', N'category-icons/Demographics-white-icon.svg');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (15, N'Climate and Lake Conditions', N'climate-and-lake-conditions', N'#2c5f72', 120, N'Greenhouse gas emissions, smoke, lake level and temperature, precipitation, and renewable energy.', N'Track how a changing climate is reaching the Tahoe Region, from smoke days and a warmer lake to less snow, and the Region''s progress cutting the emissions that drive it.', N'category-icons/Climate-white-icon.svg');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (16, N'Housing and Economy', N'housing-and-economy', N'#646820', 130, N'Housing, deed-restricted homes, prices and rents, jobs, income, and the visitor economy.', N'Track whether people who work in the Region can afford to live here, and how resilient the Region''s economy is.', N'category-icons/Housing-white-icon.svg');
INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (17, N'Aquatic Invasive Species', N'aquatic-invasive-species', N'#0d5b73', 140, N'Watercraft inspections, invasive plant control, and aquatic plant surveys.', N'Keep new aquatic invasive species out of the Region''s waters, and control and remove the ones already here.', N'category-icons/AquaticInvasiveSpecies-white-icon.svg');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (41, N'Ozone (O3)', 1, NULL, N'Ozone is monitored at a number of locations around the Lake Tahoe Basin
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (26, N'Carbon Monoxide (CO)', 1, NULL, N'Between 1983 and 1998, CO was monitored at the Horizon Hotel in Stateline, Nevada. In 1999, the monitoring site was relocated to Harvey’s Resort parking garage in Stateline, Nevada. The site is located to monitor the highest CO concentrations in the Lake Tahoe Basin because historically this area received the highest traffic volume, and is intended to be representative of both the California and Nevada sides of the South Shore Resort District. NDEP successfully petitioned the EPA to remove this monitoring site on June 30, 2012 because of the continued compliance with established CO concentration standards. CARB provided TRPA with a CO monitor which was installed on the roof of the TRPA building in Stateline, NV in 2013.', 0, N'charts', N'{"measures":[{"title":"Carbon monoxide by station","sub":"Yearly carbon monoxide (CO) statistic at each monitoring station, in parts per million. Choose a statistic.","layer":46,"where":"Pollutant = ''CO''","x":"Year","y":"Value","yLabel":"CO (ppm)","seriesBy":"Site","seriesLabel":"Station","pick":"Indicator","pickLabel":"Statistic","pickDefault":"CO - HIGH 8 HR","standard":{"field":"Threshold_Value"},"span":"span-12"},{"title":"Daily carbon monoxide by station","sub":"Daily carbon monoxide (CO) values at each station from the daily monitoring record, in the units named in each statistic. Choose a statistic.","layer":17,"where":"variable LIKE ''CO%''","x":"date","xType":"date","xLabel":"Date","y":"value","yName":"CO","yLabel":"CO","seriesBy":"id","seriesLabel":"Station","seriesNames":{"STL":"Stateline","TC":"Tahoe City","IV":"Incline Village","SLT":"South Lake Tahoe","BSP":"DL Bliss State Park","LTC":"Lake Tahoe Community College"},"pick":"variable","pickLabel":"Statistic","span":"span-12"}],"sitesLayer":{"layer":16,"name":"name","code":"id","active":"Active_2023","unit":"station"},"sitesPerYear":{"layer":46,"year":"Year","site":"Site","where":"Pollutant = ''CO''","unit":"station"}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Highest 8-Hour Average Concentration of Carbon Monoxide","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/1"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (42, N'Oxides of Nitrogen (NOX)', 1, N'The California emission inventory contains information on the following air pollution sources:
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (46, N'Particulate Matter 2.5', 1, NULL, N'Particulate matter is monitored by Placer County in Tahoe City, and at LTCC and DL Bliss as part of the national IMPROVE national monitoring network.', 0, N'charts', N'{"measures":[{"title":"Fine particulate matter by station","sub":"Yearly fine particulate matter (PM2.5) statistic at each monitoring station, in micrograms per cubic meter. Choose a statistic.","layer":46,"where":"Pollutant = ''PM2.5''","x":"Year","y":"Value","yLabel":"PM2.5 (\u00b5g/m\u00b3)","seriesBy":"Site","seriesLabel":"Station","pick":"Indicator","pickLabel":"Statistic","pickDefault":"PM2.5 - ANNUAL AVG.","standard":{"field":"Threshold_Value"},"span":"span-12"},{"title":"Daily fine particulate matter by station","sub":"Daily fine particulate matter (PM2.5) values at each station from the daily monitoring record, in the units named in each statistic. Choose a statistic.","layer":17,"where":"variable LIKE ''PM 2.5%'' OR variable LIKE ''PM2.5%''","x":"date","xType":"date","xLabel":"Date","y":"value","yName":"PM2.5","yLabel":"PM2.5","seriesBy":"id","seriesLabel":"Station","seriesNames":{"STL":"Stateline","TC":"Tahoe City","IV":"Incline Village","SLT":"South Lake Tahoe","BSP":"DL Bliss State Park","LTC":"Lake Tahoe Community College"},"pick":"variable","pickLabel":"Statistic","span":"span-12"}],"sitesLayer":{"layer":16,"name":"name","code":"id","active":"Active_2023","unit":"station"},"sitesPerYear":{"layer":46,"year":"Year","site":"Site","where":"Pollutant = ''PM2.5''","unit":"station"}}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (45, N'Particulate Matter 10', 1, NULL, N'Particulate matter is monitored in the Tahoe Basin by the California Air Resources Board at South Lake Tahoe, and is monitored as part of the national IMPROVE network sites at LTCC and DL Bliss State Park.', 0, N'charts', N'{"measures":[{"title":"Particulate matter by station","sub":"Yearly particulate matter (PM10) statistic at each monitoring station, in micrograms per cubic meter. Choose a statistic.","layer":46,"where":"Pollutant = ''PM10''","x":"Year","y":"Value","yLabel":"PM10 (\u00b5g/m\u00b3)","seriesBy":"Site","seriesLabel":"Station","pick":"Indicator","pickLabel":"Statistic","pickDefault":"PM10 - ANNUAL AVG.","standard":{"field":"Threshold_Value"},"span":"span-12"},{"title":"Daily particulate matter by station","sub":"Daily particulate matter (PM10) values at each station from the daily monitoring record, in the units named in each statistic. Choose a statistic.","layer":17,"where":"variable LIKE ''PM 10%'' OR variable LIKE ''PM10%''","x":"date","xType":"date","xLabel":"Date","y":"value","yName":"PM10","yLabel":"PM10","seriesBy":"id","seriesLabel":"Station","seriesNames":{"STL":"Stateline","TC":"Tahoe City","IV":"Incline Village","SLT":"South Lake Tahoe","BSP":"DL Bliss State Park","LTC":"Lake Tahoe Community College"},"pick":"variable","pickLabel":"Statistic","span":"span-12"}],"sitesLayer":{"layer":16,"name":"name","code":"id","active":"Active_2023","unit":"station"},"sitesPerYear":{"layer":46,"year":"Year","site":"Site","where":"Pollutant = ''PM10''","unit":"station"}}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (43, N'Regional Visibility', 1, NULL, N'Air samples needed to calculate bext were collected at least every six days at D.L. Bliss State Park. This is an appropriate site for monitoring regional conditions because it is not influenced by urban sources ((L.-W. Antony Chen, Watson, John G., and Wang, Xiaoliang 2011)). Data are collected, analyzed, and reported by the IMPROVE (national Interagency Monitoring of Protected Environments) network using nationally accepted protocols.', 0, N'charts', N'{"measures":[{"title":"Regional visibility","sub":"Three-year mean light extinction at DL Bliss State Park, in inverse megameters. Lower is clearer. Choose average (50th percentile) or worst (90th percentile) days.","layer":46,"where":"Pollutant = ''Regional Visibility''","x":"Year","y":"Value","yName":"Light extinction","yLabel":"Light extinction (Mm-1)","pick":"Indicator","pickLabel":"Statistic","pickDefault":"3-year mean (50th Percentile, Mm-1)","standard":{"field":"Threshold_Value"},"span":"span-12"}],"sitesLayer":{"layer":16,"name":"name","code":"id","active":"Active_2023","where":"id = ''BSP''","unit":"station"},"sitesPerYear":{"layer":46,"year":"Year","site":"Site","where":"Pollutant = ''Regional Visibility'' AND Value IS NOT NULL","unit":"station"}}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (44, N'Sub-Regional Visibility', 1, NULL, N'Air samples needed to calculate bext were collected at least every six days at a South Lake Tahoe site. Data were collected, analyzed and reported by the IMPROVE network using nationally accepted protocols. A monitoring site was set up at Lake Tahoe Community College in 2014.', 0, N'charts', N'{"measures":[{"title":"Sub-regional visibility","sub":"Three-year mean light extinction at South Lake Tahoe, in inverse megameters. Lower is clearer. Choose average (50th percentile) or worst (90th percentile) days.","layer":46,"where":"Pollutant = ''Sub-Regional Visibility''","x":"Year","y":"Value","yName":"Light extinction","yLabel":"Light extinction (Mm-1)","seriesBy":"Site","seriesLabel":"Station","seriesNames":{"LTCC":"Lake Tahoe Community College","SOLA":"South Lake Tahoe (1993 to 1996)"},"pick":"Indicator","pickLabel":"Statistic","standard":{"field":"Threshold_Value"},"span":"span-12"}],"sitesLayer":{"layer":16,"name":"name","code":"id","active":"Active_2023","where":"id = ''LTC''","unit":"station"},"sitesPerYear":{"layer":46,"year":"Year","site":"Site","where":"Pollutant = ''Sub-Regional Visibility'' AND Value IS NOT NULL","unit":"station"}}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (73, N'Nitrogen Dioxide (NO2)', 1, N'California: Annual average NO2 concentration not to exceed 0.030 ppm | Nevada/Federal: Annual average NO2 concentration not to exceed 0.053 ppm', N'THe California Air Resources Board (CARB) compiles data to create the criteria pollutant emission inventory, which includes information on the emissions of reactive organic gases (ROG), oxides of nitrogen (NOx), oxides of sulfur (SOx), carbon monoxide (CO), and particulate matter (PM10). Data are gathered continuously and stored in the California Emission Inventory Development and Reporting System (CEIDARS). A summary of the criteria pollutant inventory is published annually. The California emission inventory contains information on the following air pollution sources:
