INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (49, N'SEZ Basin-wide Monitoring and Assessment Plan', 5, N'The SEZ Basinwide Monitoring and Assessment Plan provides the methods and protocals to assess the current status and long-term trends of SEZs on a Basin-wide scale. The Plan will also provide a means to evaluate the impacts of ongoing and future management actions, identify regional impairments, and detect long-term trends that can inform sound future SEZ policy.', N'SEZ function is evaluated as a function of up to 10 indicators. Details on each indicator and monitoring methods are available in the plan.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (48, N'Land Coverage', 5, N'Impervious cover shall comply with the "Land Capability Classification of the Lake Tahoe Basin, California-Nevada, A Guide for Planning", Bailey, 1974. Allowable percent of impervious cover in Land Capability subclass 1a - 1 percent.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (82, N'Harmful Algae Bloom (HAB) Monitoring', 7, N'What are Harmful Algal Blooms (HABs)?
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (15, N'LTIMP', 7, NULL, N'The Lake Tahoe Interagency Monitoring Program (LTIMP) stream monitoring program was first developed in 1979 to assess sediment and nutrient input from tributaries to Lake Tahoe, and to support research that aims to understand the drivers affecting the transparency of Lake Tahoe. The tributary monitoring focuses on both event-based conditions (large runoff events associated with rainfall and snowmelt) and baseline conditions (low inflow during summer when precipitation is negligible). Up to 10 streams have been monitored since the early 1990s; five in California (Upper Truckee River, and Trout, General, Blackwood and Ward Creeks) and five in Nevada (Third, Incline, Glenbrook, Logan House, and Edgewood Creeks). Six of these streams have been monitored since water years 1980 or 1981. In water year 2012 the number of streams routinely monitored was reduced to seven (see map above), and all streams have primary monitoring stations at or near the point of discharge to Lake Tahoe.', 0, N'map', N'{"measures":[{"title":"Suspended sediment","sub":"Annual average suspended sediment concentration across Lake Tahoe Interagency Monitoring Program (LTIMP) streams.","layer":85,"x":"Year","y":"AnnualAverage","yName":"Suspended sediment","yLabel":"Concentration"},{"title":"Total phosphorus","sub":"Annual average total phosphorus concentration across LTIMP streams.","layer":88,"x":"Year","y":"AverageTotalPhosphorousConcentr","yName":"Total phosphorus","yLabel":"Concentration"},{"title":"Total nitrogen","sub":"Annual average total nitrogen concentration across LTIMP streams.","layer":87,"x":"Year","y":"AverageTotalNitrogenConcentrati","yName":"Total nitrogen","yLabel":"Concentration","span":"span-12"},{"title":"Total phosphorus samples","sub":"Total phosphorus concentration in each sample, with the state standard for the site. Choose a site.","layer":100,"x":"SampleDate_Time","xType":"date","xLabel":"Sample date","y":"TotalPhosphorus","yName":"Total phosphorus","yLabel":"Concentration","pick":"SiteName","pickLabel":"Site","standard":{"field":"State_Standard","label":"State standard"},"span":"span-12"},{"title":"Total nitrogen samples","sub":"Total nitrogen concentration in each sample, with the state standard where the site has one. Choose a site.","layer":101,"x":"SampleDatetime","xType":"date","xLabel":"Sample date","y":"Total_Nitrogen","yName":"Total nitrogen","yLabel":"Concentration","pick":"SiteName","pickLabel":"Site","standard":{"field":"State_Standard","label":"State standard"},"span":"span-12"}],"sitesLayer":{"layer":33,"name":"station_nm","code":"site_no","unit":"station"},"sitesPerYear":{"layer":99,"year":"SampleDatetime","site":"SiteName","extract":true,"unit":"station"},"siteProfile":{"record":{"layer":100,"join":{"from":"code","to":"SiteName","match":"prefix"},"year":"SampleDate_Time","extractYear":true,"value":"TotalPhosphorus","stat":"avg","label":"Total phosphorus, annual average","short":"Total phosphorus","unit":"mg/L","decimals":3,"noun":["sample","samples"],"standard":{"field":"State_Standard","label":"state standard"},"latestLabel":"Yearly average"},"related":[{"layer":101,"join":{"from":"code","to":"SiteName","match":"prefix"},"year":"SampleDatetime","extractYear":true,"value":"Total_Nitrogen","stat":"avg","label":"Total nitrogen, annual average","short":"Total nitrogen","unit":"mg/L","decimals":2,"noun":["sample","samples"],"standard":{"field":"State_Standard","label":"state standard"},"latestLabel":"Yearly average"}],"facts":[{"label":"Station number","from":"code"}],"section":{"type":"latest","title":"Latest samples"}}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Nitrogen Concentration (Tributaries)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/149"},{"Dashboard":"Threshold Dashboard","Label":"Phosphorus Concentration (Tributaries)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/150"},{"Dashboard":"Threshold Dashboard","Label":"Reduce Fine Sediment Particle Load","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/176"},{"Dashboard":"Threshold Dashboard","Label":"Reduce Total Annual Phosphorus Load","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/177"},{"Dashboard":"Threshold Dashboard","Label":"Suspended Sediment Concentration (Tributaries)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/152"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (76, N'Nearshore Human Health, E. coli Monitoring', 7, N'The Nearshore Human Health monitoring program collects Escherichia Coli (E. coli) samples to help resource managers ensure Lake Tahoe’s waters remain safe for public recreation. Water quality samples are collected between June and September at many beaches around the lake. More information about the sampling program are available here. A safe to swim map depicting recently collected E. coli data is available here.', N'Water quality samples for E. coli are taken throughout the summer at popular beaches around Lake Tahoe. E. coli is an indicator of the presence of harmful pathogens or viruses associated with recent contamination by wastewater or other fecal contamination. Individuals who swim in or contact water with elevated levels of E. coli may be at risk of getting sick because of potential exposure to harmful pathogens or viruses associated with wastewater or other fecal contamination.', 1, N'context', NULL, NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (66, N'Pelagic Water Quality (Clarity)', 7, N'Lake clarity measurements have been taken continuously by UC Davis Tahoe Environmental Research Center (TERC) since 1968, when a white disk, called the Secchi disk, could be seen down to 102 feet. It is one of the longest, unbroken clarity records in the world. Secchi depth is the most widely used method of clarity measurement, and the values are consistent with laser-based measurements also taken by TERC researchers. Water transparency in Lake Tahoe is controlled by fine particles blocking light penetration either by scattering or by absorption. The decline in transparency is the result of accumplation of fine sediment particles and growth of small phytoplankton (algae). Fine sediments and nutirents are transporated to the lake by stormwater runoff, stream erosion, and through atmospheric deposition.', N'Measurements are taken in Lake Tahoe using a 25 centimeter, all white Secchi disk. The disk is lowered into the water column from a boat to a depth at which it is no longer visible by the observer, and then raised slowly until visible again. The midpoint of these two depths is called the Secchi depth. Between 18 and 37 individual Secchi depth measurements have been collected each year at an established index station.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (13, N'Periphyton', 7, NULL, N'UC Davis has monitored periphyton in Lake Tahoe since 2000. Monitoring also occurred between 1982 and 1985 and 1989 to 1993. The primary periphyton monitoring work are regular sampling work referred to “routine” sampling at nine sites annually (the number of locations has varied historically from six to ten). At each location algal biomass (as chlorophyll a) is sampled five times annually from natural rock surfaces at a depth of 0.5 meters below the water level at the time of sampling. A second type of sampling, referred to a “synoptic” monitoring occurs once a year at 40 additional sites. The timing of synoptic monitoring varies annually and is intended to capture biomass at its peak in the spring. The synoptic monitoring includes collection of chlorophyll a at a sub-set of the sites, as well as a rapid assessment method that quantifies a periphyton biomass index (PBI).', 1, N'charts', N'{"measures":[{"title":"Periphyton at routine sites","sub":"Attached algae biomass as chlorophyll a, in milligrams per square meter. Choose a site.","layer":21,"x":"Date","xType":"date","xLabel":"Sample date","y":"value","yName":"Chlorophyll a","yLabel":"Chlorophyll a (mg/m\u00b2)","pick":"id","pickLabel":"Site","pickDefault":"Rubicon Point","span":"span-12"}],"sitesLayer":{"layer":102,"name":"SITE_NAME","status":"SiteClass"},"sitesPerYear":{"layer":21,"year":"Date","site":"id"}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Littoral Periphyton Biomass","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/175"},{"Dashboard":"Threshold Dashboard","Label":"Nearshore Attached Algae","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/109"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (16, N'Regional Stormwater Monitoring', 7, N'The Tahoe Resource Conservation District (Tahoe RCD) is leading the effort to measure pollutants in urban runoff at Lake Tahoe to help evaluate the combined effectiveness of pollutant control measures and consistently track and report monitoring findings. This effort, known as the Regional Storm Water Monitoring Program (RSWMP) is a collaborative program supported by regulatory agencies, local government representatives, and scientists in the Lake Tahoe region.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (12, N'Nearshore Turbidity Monitoring', 7, NULL, N'A pilot monitoring program of nearshore turbidity began with the first circuit completed in November 2014, followed by similar nearshore circuits completed in April, June, August and November 2015. Measurements were made at a depth of seven meters. Routine boat operating speeds are typically around 10 kilometers per hour in the nearshore areas (Heyvaert et al., 2016). Beginning 1991, nearshore turbidity was measured offshore at the 25-meter depth contour for several locations, including 1) mouth of Upper Truckee River and Trout Creek; 2) El Dorado Beach; 3) mouth of Edgewood Creek; 4) Nevada Beach; 5) mouth of Incline Creek; 6) Burnt Cedar Beach; 7) mouth of Ward Creek; 8) Tahoe State Recreation Area; and 9) the mouth of Blackwood Creek. More recently, nearshore clarity has been measured at approximately the seven-meter contour following a continuous circuit around the lakeshore.', 0, N'charts', N'{"measures":[{"title":"Nearshore turbidity by location","sub":"Turbidity in nephelometric turbidity units (NTU) at each nearshore location, by year.","layer":111,"x":"Year","y":"value","unpivot":{"prefix":"NTU"},"yName":"Turbidity","yLabel":"Turbidity (NTU)","seriesBy":"Location","seriesLabel":"Location","span":"span-12"},{"title":"Turbidity at one location","sub":"Turbidity in NTU each year at one nearshore location. Choose a location.","layer":111,"x":"Year","y":"value","unpivot":{"prefix":"NTU"},"yName":"Turbidity","yLabel":"Turbidity (NTU)","type":"bar","pick":"Location","pickLabel":"Location","span":"span-12"}]}', N'[{"Dashboard":"Threshold Dashboard","Label":"Nearshore Turbidity (No Stream Influence)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/136"},{"Dashboard":"Threshold Dashboard","Label":"Nearshore Turbidity (Stream Influence)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/135"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (10, N'Phytoplankton Primary Productivity', 7, N'Maintain annual mean phytoplankton primary productivity at or below 52gmC/m2/yr.', N'Phytoplankton PPr measurements at Lake Tahoe have been made following the same standard operating procedure since the first observations were made in 1967 (Winder et al., 2009). Lake water is collected at the TERC west shore index station, which was found to be representative of the lake’s deepwater condition (Charles Remington Goldman, 1974). For each sampling event, water samples are collected from 13 different depths (between 0-105m) spanning the photic zone (i.e., the vertical zone in the water column exposed to sufficient sunlight for photosynthesis to occur), and analysed to determine carbon assimilation rates using very sensitive methods needed for pristine or oligotrophic waters (Charles Remington Goldman, 1974). Values from the various samples are aggregated to yield a depth-integrated PPr value. These depth-integrated values are aggregated over the calendar year to generate an estimate of annual average phytoplankton primary productivity.', 0, N'charts', N'{"measures":[{"title":"Phytoplankton primary productivity","sub":"Annual mean algal growth at the Lake Tahoe Index Station, in grams of carbon per square meter per year. The threshold standard is 52.","layer":75,"x":"Year","y":"Primary_Productivity","yName":"Primary productivity","yLabel":"Primary productivity (gC/m2/yr)","standard":{"value":52},"span":"span-12"}]}', N'[{"Dashboard":"Threshold Dashboard","Label":"Phytoplankton Primary Productivity (Pelagic)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/113"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (11, N'Vertical Extinction Coefficient', 7, N'The vertical extinction coefficient must be less than 0.08 per meter when measured at any depth below the first meter (California and Nevada state standard).', N'VEC is measured at the Lake Tahoe Index Station at least 24 times annually and at least 12 times annually at the mid-lake station. VEC is measured by lowering a submersible photometer down through the water column.', 0, N'charts', N'{"measures":[{"title":"Vertical extinction coefficient","sub":"Annual average light extinction at the Lake Tahoe Index Station, per meter, with one standard deviation above and below. Higher values mean less clear water.","layer":89,"x":"Year","y":[{"field":"Annual_Average","name":"Annual average"},{"field":"sd_plus1","name":"Plus one standard deviation"},{"field":"sd_minus1","name":"Minus one standard deviation"}],"yLabel":"VEC (1/m)","standard":{"field":"State_Standard","label":"State standard"},"zero":false,"span":"span-12"}]}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9777, N'Phosphorus Load Reduction', 7, N'Phosphorus is a nutrient important to the growth and reproduction of plants and is considered a pollutant of concern in the Lake Tahoe Region. Nitrogen and phosphorus together support the growth of algae in Lake Tahoe and contribute to the decline in water transparency and adversely affect nearshore aesthetics. Landscape disturbances including impervious surfaces, residential and commercial development, wildfire, and the degradation of stream environment zones (SEZs), can contribute to sediment and nutrient inputs to the lake or its tributaries. Projects such as restoring SEZ and limiting fertilizer use in the Region seek to reduce phosphorous in Lake Tahoe''s tributaries. Phosphorous reductions are monitored by partners through the Lake Tahoe Total Maximum Daily Load Program (TMDL).
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9778, N'Nitrogen Load Reduction', 7, N'Nitrogen is a nutrient important to the growth and reproduction of plants, and it is considered a pollutant of concern in the Lake Tahoe Region. Nitrogen and phosphorus together support the growth of algae in Lake Tahoe. Free-floating algae occur throughout Lake Tahoe and contribute to the decline in water transparency and attached algae coat rocks in the nearshore, adversely affecting nearshore aesthetics. Landscape disturbances including, but not limited to, impervious road and parking lot surfaces, residential and commercial development, wildfire, and the degradation of stream environment zones, can contribute to sediment and nutrient inputs to the lake or its tributaries. Weather variations and their effects on stream hydrology (particularly the extremes of droughts and floods), and long-term climate change are considered among the most important environmental drivers of tributary runoff. Nitrogen load reductions are monitored by partners through the Lake Tahoe Total Maximum Daily Load Program (TMDL).
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9779, N'Fine Sediment Load Reduction', 7, N'In an undisturbed watershed, the majority of stormwater is captured by vegetation and absorbed and filtered through the soil. Development, such as roads, driveways, and rooftops alter the watershed by creating impervious surfaces that prevent stormwater from infiltrating. Instead, stormwater runs over impervious surfaces, collecting pollutants such as suspended sediment as it travels, enters the nearest storm drain or stream, and ultimately ends up in Lake Tahoe. Pollutants, including suspended sediment, contribute to the decline in lake clarity. The Lake Tahoe TMDL is the Region’s science-based strategy to reduce pollutant loading to Lake Tahoe and restore the historic clarity of the Lake.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (65, N'Noise - Highways', 9, N'TRPA regularly monitors noise along highway corridors in the Lake Tahoe Basin to ensure noise limits are not being exceeded. Because noise from highways is the largest source of background noise in the Basin, noise limits near highways ensures the serenity of the Tahoe Basin is maintained. High noise levels can reduce the public’s enjoyment of the natural environment, impact quality of life for residents, and disturb native wildlife.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (61, N'Noise - Plan Areas', 9, N'TRPA monitors background noise levels in all Plan Areas in the Tahoe Basin to ensure noise levels are not disturbing people and wildlife, and to maintain the unique characteristics of the Basin. Each Plan Area has its own allowable noise level in TRPA''s thresholds, with maximum average 24-hour allowable noise levels ranging from 45 decibles (dB) in wilderness areas to 65 dB in industrial areas. High noise levels can reduce the public’s enjoyment of the natural environment, impact quality of life for residents, and disturb native wildlife.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (62, N'Noise - Shorezone', 9, N'TRPA regularly monitors noise from motorized watercraft in the shorezone of Lake Tahoe to ensure noise levels are not being exceeded. Shorezone noise limits are in place to maintain the serenity of Lake Tahoe and to protect sensitive wildlife.', N'TRPA regulalry monitors noise in the shorezone from motorized watercraft at up to ten locations around Lake Tahoe. Noise monitors are deployed for at least two weeks during peak boating season which occurs July 4th to Labor Day. Noise monitors automatically record all single noise events that exceed 75 decibles (dB), the noise limit for shorezone areas. Afterward, all noise events exceeding 75 dB are listened to by a noise technician to distinguish noise exceedancs from watercraft and non-watercraft. Noise monitors are regularly calibrated to industry standards to ensure accuracy.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (8, N'Watercraft Noise', 9, N'The following maximum noise levels are allowed: Watercraft: Stationary Test - 90 dBA Lmax for boats manufactured after January 1, 1993; Microphone 3.3 feet from exhaust outlet - 5 feet above water.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9, N'Cumulative Noise Events', 9, N'Background noise levels shall not exceed the following levels: 45 dBA CNEL (Average Noise Level) in the Critical Wildlife Habitat Areas Land Use Category.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (60, N'Aircraft Noise', 9, N'The following maximum noise levels are allowed: Aircraft measured 6,500 m-start of takeoff roll 2,000 m-runway threshold approach: Aircraft measured 6,500 m-start of takeoff roll 2,000 m-runway threshold approach:
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (33, N'Bicycle and Pedestrian', 10, N'TRPA and local partners monitor bicycle and pedestrian activity throughout the Region to understand high use areas, mode-split, and support grant applications and reporting. Count information also informs policies and programs targeted to improve and support active transportation.', N'In 2015, as part of the update to the Active Transportation Plan, TRPA developed the Lake Tahoe Region Bicycle and Pedestrian Monitoring Protocol using best industry practices and national experts Kittleson and Associates. TRPA began implementation in summer of 2015, which built on and integrated previous monitoring efforts. In partnership with local agencies, TRPA has established a system for the collection of year-round active transportation data which includes permanent counting stations, biennial count locations, and spot count locations depending on need. During the first two years of implementation, TRPA produced a bicycle and pedestrian monitoring report which analyzes historical trends, provides detailed information by location, and compares use at similar sites. This report also supplemented the regional transportation monitoring report. Moving forward, all analysis and up-to-date data will be available on the transportation monitoring dashboard, in lieu of a hardcopy report.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (77, N'Congestion-Travel Time', 10, N'TRPA monitors congestion on roadways throughout the region to assist with regional transportation planning. A well executed transportation management system incorporates monitoring data, real-time information, and dynamic operations that respond to seasonal congestion and periodic congestion.', N'Congestion can be characterized by many metrics and sourced from a variety of different data sources. For the purpose of analyzing congestion in the Tahoe region, TRPA uses the Regional Integrated Transportation Information System (RITIS) probe data analytics suite, provided by the Federal Highway Administration.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (34, N'Safety', 10, N'Safety is a regional transportation plan goal and policy because it is critical that everyone feel comfortable traveling at Lake Tahoe, whether they are walking, taking the bus, riding a bike or driving a car. Safety is not only an important goal for Tahoe, the Federal Highway Administration (FHWA) recently established five safety performance measures. FHWA Safety (PM 1) Final Rule, effective April 14, 2016, supported the data-driven performance focus of the Highway Safety Improvement Program and established performance measures for which states and Metropolitan Planning Organizations must develop targets.', N'Safety performance measures help to assess fatalities and serious injury on all public roads regardless of ownership or functional classification. These measures are required to be incorporated into the regional transportation plan and state’s Highway Safety Improvement Programs. To support meeting these targets, a Lake Tahoe Region Safety Plan is underdevelopment which outlines crash trends, risk factors, gaps in data, and recommends strategies and designs to improve safety for all roadway users. Crash data is provided by the state of California and Nevada and consolidated by TRPA.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (64, N'Traffic Volumes', 10, N'In partnership with the state DOTs, TRPA collects, monitors, and analyzes roadway traffic volume data from several dozen count stations throughout the Tahoe region.', N'Traffic volume monitoring is part of a regional strategy to create a well executed transportation management system that incorporates monitoring data, real-time information, and dynamic operations that respond to seasonal and periodic congestion. Over the last few years, intelligent transportation systems have seen significant advancements and deployments in the areas of data collection, data sharing, mobile solutions, and traffic monitoring capabilities. Both the California Department of Transportation (Caltrans) and the Nevada Department of Transportation (NDOT) manage several dozen permanent traffic count stations, which collect data on the number of vehicles traveling throughout the region. TRPA aggregates and analyzes this data for a variety of purposes, including project planning, development of our Regional Transportation Plan, and travel demand modeling.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (36, N'Transit', 10, N'TRPA conducts on-going monitoring to inform transportation policy and programs with the goal of providing a successful multi-modal transportation system that appeals to users, supports mobility needs, and decreases dependency on the private automobile. TRPA has been monitoring transportation performance since the early 1970s including traffic counts, travel mode choice, and demographic and air quality trends so that planners can evaluate the Lake Tahoe Region’s transportation system and use best available science to inform policy-making. The 2016 FAST Act requires states and MPOs to develop targets for specific performance measures related to safety, transit, and roadway/bridge conditions. To comply with FAST Act regulations, TRPA has prioritized identifying performance measures and setting targets for transit to help transit agencies improve the efficiency and effectiveness of the level of service they provide in Tahoe.', N'TTD, TRPA, and TART work together in corridor and transit planning. Consistent transit rider surveys and operations data collection help determine the need for additional services and operating hours. Based on reporting requirements, TRPA''s Productivity Improvement Program (PIP), and goals outlined in the Regional Transportation Plan, Long Range Transit Master Plan, and each transit agency''s Short Range Transit Plans, the Tahoe transit monitoring program is built to track the following: Deadhead Miles and Hours, Ridership, Transit Mode Share, Productivity, On Time Performance, Operating Cost, Farebox Recovery, Rolling Stock, Equipment, Facilities, and Infrastructure. To find out more about these performance measures, take a look at the Tahoe Transit Monitoring Program: Monitoring Protocol.', 1, N'charts', N'{"measures":[{"title":"Transit routes by provider","sub":"Routes in the consolidated Tahoe transit route layer, by operator.","layer":2,"x":"PROVIDER","xType":"category","xLabel":"Provider","y":"OBJECTID","stat":"count","yName":"Routes","yLabel":"Routes","seriesBy":"SEASON","seriesLabel":"Season","type":"stacked","span":"span-12"}],"mapLayer":{"layer":2,"title":"Transit routes","unit":"route","unitPlural":"Routes","name":"ROUTE_NAME","geometry":"line","colorBy":"PROVIDER","colorByLabel":"Provider","colors":{"TART":"#3e72b0","TTD":"#e49937","SSTMA":"#89bf40"},"meta":[{"field":"PROVIDER"},{"field":"SEASON"}],"fields":[{"field":"ROUTE_NUMBER","label":"Route"},{"field":"PROVIDER","label":"Provider"},{"field":"SEASON","label":"Season"},{"field":"Frequency","label":"Frequency"},{"field":"WEBSITE","label":"Website"}]}}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Transportation","Url":"https://climate.laketahoeinfo.org/transportation"},{"Dashboard":"Transportation Tracker","Label":"Data Trends","Url":"https://transportation.laketahoeinfo.org/transportation/data-trends"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (69, N'Travel Behavior', 10, N'Since 2006 TRPA has conducted basin-wide travel surveys every two years in order to better understand basic travel characteristics of both residents and visitors. The data collected - which includes data points such as mode share, origin-destinations, and trip purpose - is used for a variety of purposes at TRPA including regional performance metrics, project planning, and travel demand modelling.', N'The dashboard below summarises TRPA''s 2018 Summer Travel Survey, which was conducted in late-August of 2018.', 1, N'charts', N'{"measures":[{"title":"Vehicle miles traveled","sub":"Estimated vehicle miles traveled (VMT) in the Tahoe Region.","layer":92,"x":"Year","y":"VMT","yName":"VMT","yLabel":"Vehicle miles traveled","span":"span-12"}]}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Transportation","Url":"https://climate.laketahoeinfo.org/transportation"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (47, N'Vehicle Miles Traveled', 10, N'Reduce vehicle miles of travel in the Basin by 10 percent of the 1981 base year values', N'The identification of traffic volumes is a primary component towards tracking
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9790, N'Seral Stage and Canopy Cover', 11, N'Seral stage is the developmental phase of a forest, from young regeneration to mature stands of large trees. Canopy cover is the share of the forest floor shaded by tree crowns, from open to closed. Together they shape how a forest grows and changes, and the wildlife and ecosystems it can support.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9789, N'Stand Density', 11, N'Stand density measures how many trees grow in an area (trees per acre) and the total cross-section of their trunks (basal area, in square feet per acre).
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9794, N'Large Trees', 11, N'Large trees, more than 36 inches in diameter at breast height, are the backbone of an old forest. They store the most carbon, survive low-intensity fire behind thick bark, and give nesting and denning sites to wildlife such as the California spotted owl, northern goshawk, and Pacific marten.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9795, N'Tree Mortality', 11, N'Tree mortality is the forest dying faster than it grows back. Drought weakens trees, and bark beetles and other insects kill the weakened ones, often across whole hillsides. Dense stands, where trees compete for water, are hit hardest.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (83, N'Subalpine Conifer', 11, N'A monitoring program to track the non-degradation of subalpine conifer species, including the endangered whitebark pine.', N'Ground-based plot data that inform remote sensing techniques to track change over time in species composition, health, and distribution in the subalpine zone.', 0, N'context', N'{"measures":[{"title":"Subalpine conifer acres by dominant tree","sub":"Acres of subalpine conifer forest by dominant tree, from the 2010 EcObject LiDAR vegetation map.","layer":98,"where":"WHRTYPE = ''SCN''","x":"REGIONAL_DOMINANCE_TYPE_1","xType":"category","xLabel":"Dominant tree","xNames":{"SA":"Subalpine conifer mix","WB":"Whitebark pine","WW":"Western white pine","MH":"Mountain hemlock"},"y":"Acres","stat":"sum","yName":"Acres","yLabel":"Acres","type":"bar","orientation":"h","sort":"desc"},{"title":"Subalpine conifer acres by tree size","sub":"Acres by California Wildlife Habitat Relationships tree size class (2010).","layer":98,"where":"WHRTYPE = ''SCN''","x":"WHRSIZE","xType":"category","xLabel":"Tree size","xNames":{"2":"Sapling (1 to 6 in.)","3":"Pole (6 to 11 in.)","4":"Small tree (11 to 24 in.)","5":"Medium to large (over 24 in.)","6":"Multilayered"},"y":"Acres","stat":"sum","yName":"Acres","yLabel":"Acres","type":"bar"}]}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (58, N'Late Seral and Old Growth Forest', 11, N'48 percent of the Montane zone (lower than 7,000 feet elevation) must be in a late seral or old growth condition; the Montane zone will contribute 20 percent (30,600 acres) of forested lands towards VP12.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (21, N'Yellow Pine and Red Fir Abundance', 11, N'Relative Abundance - Of the total amount of undisturbed vegetation in the Tahoe Basin: Maintain 15-25 percent of the Red Fir Forest in seral stages other than mature.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (81, N'EcObject Forest Monitoring', 11, N'The LTBMU EcObject product represents a novel forest-wide existing vegetation dataset produced by Region 5 Remote Sensing Lab that incorporates Light Detection and Ranging (LiDAR) into several facets of the mapping process. It is created from a multi-resolution segmentation of LiDAR-derived tree approximate objects and a 1-m canopy height model, which were then aggregated by stand and tree-level ecologic relationships. The resulting segments were then populated with a collection of traditional and contemporary metrics at scales that benefit both project-level planning and large-landscape analysis. Different combinations of multi-dimensional datasets were used to estimate metrics and thus accuracies vary depending upon both the data used and workflows that were generated. This guide is intended to describe the different map attributes, how they were generated and computed, as well as any known limitations of
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9680, N'Limit Size of New Forest Openings', 11, N'The indicator discourages the creation of large forest openings, such as clear cuts, while allowing for forest openings of up to eight acres to meet management goals such as regeneration of shade intolerant species (e.g., Jeffrey and sugar pine). Regulatory protections in the Code of Ordinances prescribe forestry operations to limit the size of new forest openings.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9681, N'Stand Composition and Age', 11, N'The stand composition and age management standard encourages the perpetuation of a diversity of tree age classes, which is important for ensuring the sustainability of the Tahoe Region’s forests. Prior to European settlement, low intensity fires burned every five to 18 years in lower elevation pine and mixed conifer forests in the Tahoe Region. As a result, these lower elevation forests in the Region typically had large, widely spaced conifers with a poorly developed shrub understory, in a mosaic pattern of different age classes from some higher-intensity, stand-replacing fires. The TRPA Code of Ordinances prohibits the manipulation of vegetation that would permanently impact forest integrity. Fuels reduction projects generally include understory ladder fuel removal and forest thinning, but do not homogenize the vegetative landscape when interspersed among dense, even-aged untreated forest acres. This approach results in the desired mosaic pattern across a large area.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9684, N'Appropriate Forest Management Practices', 11, N'The standard ensures that forest management activities comply with all Tahoe Regional Plan policies and ordinances adopted to achieve multiple threshold standards. Forest management activities have the potential for substantial impacts on the environment. However, the forests of the Tahoe Region need active management to maintain forest health and reduce the threat of wildfire. TRPA and other agencies have incorporated appropriate forest management policies into their respective planning documents to ensure their application during the implementation of forestry projects. The vast majority of forest management work in the Tahoe Region is completed using either hand crews or low-impact ground-based equipment; however, helicopters and cable yarding have been used. Low-impact ground-based equipment is typically rubber-tired machines that exert low ground pressure, and therefore cause less ground disturbance and soil compaction than traditional forest management equipment.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9796, N'Annual Burn Probability', 12, N'Annual burn probability is the chance that a given spot in the Basin burns in any one year. It comes from simulating thousands of fire seasons over the Basin''s own fuels, weather, topography, and history of ignitions, and counting how often each 30-meter cell burns.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9797, N'Likely Fire Severity', 12, N'Fire has long shaped Sierra Nevada forests. Frequent, low-intensity fire every decade or two at Tahoe''s lower elevations kept fuels in check and forests open and diverse. A century of fire suppression has let fuels build up and forests become overstocked, raising the risk of large, high-severity fires that burn hotter, are harder to control, and can damage soils, wildlife habitat, communities, and infrastructure.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9798, N'Area Burned', 12, N'Area burned is the acres of wildfire inside the Basin each year. It is the observed record that the modeled measures, burn probability and likely fire severity, are checked against.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (39, N'Tahoe Yellow Cress Monitoring', 13, N'Tahoe Yellow Cress (TYC, Rorippa subumbellata) is a small native plant that grows on the shoreline of Lake Tahoe and no where else in the world. It lives only on the sandy beaches and dunes at the ever-changing margin of the lake. Impacts from recreation and development first led to conservation concerns in the 1970’s and TYC has been listed as endangered in both states since 1982. In 1999, a multi-agency and private interest group task force was formed to develop and implement a conservation strategy to promote the recovery and conservation of TYC. The conservation strategy provides an adaptive management framework and options for avoiding, minimizing, and mitigating impacts to TYC and its habitat on public and private lands. The TYC Stewardship Program recognizes the critical role of private landowners in ensuring the long-term survival of TYC.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (54, N'Tahoe Draba', 13, N'The monitoring objective is to provide a quantitative and consistent method for evaluating status and trend, especially at sites comprised of large numbers of plants where it is difficult to accurately count individuals. Monitoring in permanent plots allows for more repeatable and efficient surveys. Demographic data, climate patterns, and associated plant community and site data will help interpret status and trend changes.', N'U.S. Forest Service monitoring of Tahoe draba began in 2004 when plants were located and counted at 22 subpopulation sites (Engelhardt and Gross 2013). An additional 3 sites were added in a limited survey in 2005. All sites were re-surveyed in 2009 and 9 new sites were added. In 2013 six sites were revisited and one new site was discovered, and in 2014 14 sites were revisited. All known subpopulations are censused by LTBMU staff every 5 years at a minimum. A comprehensive long-term monitoring program for Tahoe draba was initiated in 2009 when plots were installed at seven subpopulation sites within three LTBMU populations (Engelhardt and Gross 2011a). Monitoring plots were established at three subpopulations within two populations (Relay Peak and Mt. Rose Ski Area) on the Humboldt-Toiyabe National Forest in 2011. Monitoring occurred two years after plot establishment to collect baseline data, and will occur every 3 to 5 years until the species is no longer considered sensitive.', 0, N'map', N'{"measures":[{"title":"Subpopulations over time","sub":"Known Tahoe draba subpopulations in each survey year, with the threshold minimum, 2023 Threshold Evaluation.","json":"data/threshold-evaluation/tahoe-draba-subpopulations.json","sourceHref":"https://trpa-agency.github.io/ThresholdEvaluation/2023/Vegetation/Chart/Final/Vegetation_TahoeDraba.html","sourceLabel":"2023 Threshold Evaluation","x":"Year","y":"Subpopulations","yName":"Subpopulations","yLabel":"Subpopulations","type":"bar","standard":{"field":"Threshold"},"span":"span-12"},{"title":"Subpopulation sites by population","sub":"Mapped Tahoe draba subpopulation sites in each population, with the threshold minimum.","service":"https://maps.trpa.org/server/rest/services/Vegetation/MapServer","layer":1,"where":"USDA_Code = ''DRASA2''","x":"EOName","xType":"category","xLabel":"Population","y":"OBJECTID","stat":"count","yName":"Subpopulation sites","yLabel":"Subpopulation sites","type":"bar"},{"title":"Plants by population","sub":"Plants counted or estimated at the last survey of each site (USFS, through 2018).","service":"https://maps.trpa.org/server/rest/services/Vegetation/MapServer","layer":1,"where":"USDA_Code = ''DRASA2''","x":"EOName","xType":"category","xLabel":"Population","y":"PlantCount","stat":"sum","yName":"Plants","yLabel":"Plants","type":"bar"}],"mapLayer":{"service":"https://maps.trpa.org/server/rest/services/Vegetation/MapServer","layer":1,"where":"USDA_Code = ''DRASA2''","title":"Tahoe draba subpopulations","unit":"subpopulation","unitPlural":"Subpopulations","name":"SITE_ID_FS","countAsSites":false,"colorBy":"EOName","colorByLabel":"Population","colors":{"Freel Peak":"var(--mon-stevens4-1)","Heavenly":"var(--mon-stevens4-2)","Hell Hole":"var(--mon-stevens4-3)","Relay Peak":"var(--mon-stevens4-4)"},"meta":[{"field":"EOName"},{"field":"PlantCount","suffix":" plants"}],"fields":[{"field":"EOName","label":"Population"},{"field":"PlantCount","label":"Plants"},{"field":"CountType","label":"Count type"},{"field":"SurveyLast","label":"Last survey"},{"field":"Acres","label":"Acres"}]}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Tahoe Draba (Draba asterophora var. asterophora)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/90"}]');
