INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (50, N'Osgood Swamp', 13, N'Two recent different monitoring approaches have been implemented at Osgood Swamp. As part of the Region 5 Fen Assessment program, a total of 135 potential fens, including Osgood Swamp, have been assessed within the Lake Tahoe Region since 2006 (Sikes et al., 2011). Of these, a total of 47 locations have been confirmed as fens. In 2010, the U.S. Forest Service collaborated with the California Native Plant Society to develop a quantitative system for ranking the ecological integrity and quality of fens (Sikes et al., 2011). Using this ranking system, surveyors objectively score a fen on eight different criteria on a five-point scale. The criteria include factors such as rarity, biodiversity, impacts, accessibility, and uniqueness. The conservation significance rank is the sum of scores for each criterion and has a maximum value of 40 points. This protocol rates the condition of the fen, but does not provide enough detail to monitor status and trends over time.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (25, N'Pope Marsh', 13, N'Provide for the nondegradation of the natural qualities of any plant community that is uncommon to the Region or of exceptional scientific, ecological, or scenic value. The threshold standard shall apply, but not be limited to, 1) the deep-water plants of Lake Tahoe, 2) Grass Lake, 3) Osgood Swamp, 4) Hell Hole, 5) Upper Truckee Marsh, 6) Taylor Creek Marsh, 7) Freel Peak Cushion Plant Community, and 8) Pope Marsh.', N'The status and trend determinations were based on a qualitative assessment of factors influencing the condition of the site, including historical alterations, ongoing hydrologic impacts, sources of recreation-related disturbance, and surrounding land use and resource management. However, in the future it will be possible to base the evaluation on quantitative vegetation monitoring data. Two permanent plots following the protocol in the Region 5 Range Monitoring Program were installed at Pope Marsh in 2004 (Weixelman 2011). These plots are on the north-east and north west portions of Pope Marsh. The protocol is designed to classify a meadow according to wetland index and plant functional types, which provides a quantitative ecological condition scorecard for that meadow type (Weixelman and Gross In Review). The plots were visited in 2009/2010 and 2014/2015 and the USFS is in the process of analyzing the data (Engelhardt and Gross 2011b; Shana Gross pers. comm.). Distance to meadow edge,', 0, N'map', N'{"measures":[{"title":"Overall condition score","sub":"SEZ assessment score by threshold evaluation year, meadow units.","layer":106,"where":"Assessment_Unit_Name IN (''Pope marsh meadow'') AND SEZ_Type LIKE ''%Meadow%''","x":"Threshold_Year","xType":"category","xLabel":"Evaluation year","y":"Final_Percent","stat":"avg","seriesBy":"Assessment_Unit_Name","seriesLabel":"Assessment unit","yLabel":"Score (percent)","type":"bar"},{"title":"Vegetation indicator scores","sub":"Points out of 12 (A 12, B 9, C 6, D 3), meadow units.","layer":106,"where":"Assessment_Unit_Name IN (''Pope marsh meadow'') AND SEZ_Type LIKE ''%Meadow%''","x":"Threshold_Year","xType":"category","xLabel":"Evaluation year","y":[{"field":"VegetationVigor_Score","name":"Vegetation vigor"},{"field":"Invasives_Scores","name":"Invasive species"},{"field":"Conifer_Encroachment_Score","name":"Conifer encroachment"}],"yLabel":"Points","type":"bar","pick":"Assessment_Unit_Name","pickLabel":"Assessment unit"}],"mapLayer":{"layer":106,"where":"Assessment_Unit_Name IN (''Pope marsh meadow'')","title":"SEZ assessment unit","unit":"assessment unit","unitPlural":"Assessment units","name":"Assessment_Unit_Name","colorBy":"Final_Rating","colorByLabel":"Overall rating","colors":{"A":"var(--mon-chlorophyll-6)","B":"var(--mon-chlorophyll-5)","C":"var(--mon-chlorophyll-3)","D":"var(--mon-chlorophyll-2)","Not Assessed":"var(--color-content-disabled)"},"labels":{"A":"Rating A","B":"Rating B","C":"Rating C","D":"Rating D"},"pick":"Threshold_Year","pickLabel":"Evaluation year","meta":[{"field":"SEZ_Type"},{"field":"Acres","suffix":" acres"}],"fields":[{"field":"Final_Rating","label":"Overall rating"},{"field":"Final_Percent","label":"Score (percent)"},{"field":"VegetationVigor_Rating","label":"Vegetation vigor"},{"field":"Invasive_Rating","label":"Invasive species"},{"field":"Conifer_Encroachment_Rating","label":"Conifer encroachment"},{"field":"Acres","label":"Acres"}]},"overlays":[{"layer":42,"title":"Aquatic vegetation survey zones","name":"Location_1","geometry":"fill","color":"var(--mon-stevens4-1)","where":"Location_1 = ''Pope Marsh''","fields":[{"field":"Strata","label":"Stratum"}]}]}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (23, N'Upper Truckee Marsh', 13, NULL, N'The status and trend determinations were based on a qualitative assessment of factors influencing the condition of the site, including historical alterations, ongoing hydrologic impacts, sources of recreation-related disturbance, and surrounding land use and management. Two long term meadow monitoring plots were installed in the Upper Truckee Marsh in 2014, following the protocol in the U.S. Forest Service Region 5 Range Monitoring Program (Weixelman 2011). The protocol is designed to classify a meadow according to wetland index and plant functional types, which provides a quantitative ecological condition scorecard for that meadow type (Weixelman and Gross In Review). Distance to meadow edge, distance to stream channel, degree of channel incision, and evidence of Sierra lodgepole pine (Pinus contorta var. murrayana) encroachment data is collected at each transect.', 0, N'map', N'{"measures":[{"title":"Overall condition score","sub":"SEZ assessment score by threshold evaluation year, meadow units.","layer":106,"where":"Assessment_Unit_Name IN (''UTR marsh - Trout Creek side'', ''UTR Marsh - UTR side'') AND SEZ_Type LIKE ''%Meadow%''","x":"Threshold_Year","xType":"category","xLabel":"Evaluation year","y":"Final_Percent","stat":"avg","seriesBy":"Assessment_Unit_Name","seriesLabel":"Assessment unit","yLabel":"Score (percent)","type":"bar"},{"title":"Vegetation indicator scores","sub":"Points out of 12 (A 12, B 9, C 6, D 3), meadow units.","layer":106,"where":"Assessment_Unit_Name IN (''UTR marsh - Trout Creek side'', ''UTR Marsh - UTR side'') AND SEZ_Type LIKE ''%Meadow%''","x":"Threshold_Year","xType":"category","xLabel":"Evaluation year","y":[{"field":"VegetationVigor_Score","name":"Vegetation vigor"},{"field":"Invasives_Scores","name":"Invasive species"},{"field":"Conifer_Encroachment_Score","name":"Conifer encroachment"}],"yLabel":"Points","type":"bar","pick":"Assessment_Unit_Name","pickLabel":"Assessment unit"}],"mapLayer":{"layer":106,"where":"Assessment_Unit_Name IN (''UTR marsh - Trout Creek side'', ''UTR Marsh - UTR side'')","title":"SEZ assessment unit","unit":"assessment unit","unitPlural":"Assessment units","name":"Assessment_Unit_Name","colorBy":"Final_Rating","colorByLabel":"Overall rating","colors":{"A":"var(--mon-chlorophyll-6)","B":"var(--mon-chlorophyll-5)","C":"var(--mon-chlorophyll-3)","D":"var(--mon-chlorophyll-2)","Not Assessed":"var(--color-content-disabled)"},"labels":{"A":"Rating A","B":"Rating B","C":"Rating C","D":"Rating D"},"pick":"Threshold_Year","pickLabel":"Evaluation year","meta":[{"field":"SEZ_Type"},{"field":"Acres","suffix":" acres"}],"fields":[{"field":"Final_Rating","label":"Overall rating"},{"field":"Final_Percent","label":"Score (percent)"},{"field":"VegetationVigor_Rating","label":"Vegetation vigor"},{"field":"Invasive_Rating","label":"Invasive species"},{"field":"Conifer_Encroachment_Rating","label":"Conifer encroachment"},{"field":"Acres","label":"Acres"}]},"overlays":[{"layer":42,"title":"Aquatic vegetation survey zones","name":"Location_1","geometry":"fill","color":"var(--mon-stevens4-1)","where":"Location_1 LIKE ''Upper Truckee Marsh%''","fields":[{"field":"Strata","label":"Stratum"}]}]}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (24, N'Taylor Creek Marsh', 13, NULL, N'The status and trend determinations were based on a qualitative assessment of factors influencing the condition of the site including historical alterations, ongoing hydrologic impacts, sources of recreation-related disturbance, and surrounding land use and management. One permanent plot, following the protocol in the Region 5 Range Monitoring Program, was installed at Taylor Creek Marsh in 2004 (Weixelman 2011). Two plots were installed in 2004 in the adjacent Tallac Creek Meadow. The protocol is designed to classify a meadow according to wetland index and plant functional types, which provides a quantitative ecological condition scorecard for that meadow type (Weixelman and Gross In Review). The plots were re-visited in 2009/2010 and 2014/2015 but the data is not yet available (Engelhardt and Gross 2011b).', 0, N'map', N'{"measures":[{"title":"Overall condition score","sub":"SEZ assessment score by threshold evaluation year, meadow units.","layer":106,"where":"Assessment_Unit_Name IN (''Taylor Creek marsh'') AND SEZ_Type LIKE ''%Meadow%''","x":"Threshold_Year","xType":"category","xLabel":"Evaluation year","y":"Final_Percent","stat":"avg","seriesBy":"Assessment_Unit_Name","seriesLabel":"Assessment unit","yLabel":"Score (percent)","type":"bar"},{"title":"Vegetation indicator scores","sub":"Points out of 12 (A 12, B 9, C 6, D 3), meadow units.","layer":106,"where":"Assessment_Unit_Name IN (''Taylor Creek marsh'') AND SEZ_Type LIKE ''%Meadow%''","x":"Threshold_Year","xType":"category","xLabel":"Evaluation year","y":[{"field":"VegetationVigor_Score","name":"Vegetation vigor"},{"field":"Invasives_Scores","name":"Invasive species"},{"field":"Conifer_Encroachment_Score","name":"Conifer encroachment"}],"yLabel":"Points","type":"bar","pick":"Assessment_Unit_Name","pickLabel":"Assessment unit"}],"mapLayer":{"layer":106,"where":"Assessment_Unit_Name IN (''Taylor Creek marsh'')","title":"SEZ assessment unit","unit":"assessment unit","unitPlural":"Assessment units","name":"Assessment_Unit_Name","colorBy":"Final_Rating","colorByLabel":"Overall rating","colors":{"A":"var(--mon-chlorophyll-6)","B":"var(--mon-chlorophyll-5)","C":"var(--mon-chlorophyll-3)","D":"var(--mon-chlorophyll-2)","Not Assessed":"var(--color-content-disabled)"},"labels":{"A":"Rating A","B":"Rating B","C":"Rating C","D":"Rating D"},"pick":"Threshold_Year","pickLabel":"Evaluation year","meta":[{"field":"SEZ_Type"},{"field":"Acres","suffix":" acres"}],"fields":[{"field":"Final_Rating","label":"Overall rating"},{"field":"Final_Percent","label":"Score (percent)"},{"field":"VegetationVigor_Rating","label":"Vegetation vigor"},{"field":"Invasive_Rating","label":"Invasive species"},{"field":"Conifer_Encroachment_Rating","label":"Conifer encroachment"},{"field":"Acres","label":"Acres"}]},"overlays":[{"layer":42,"title":"Aquatic vegetation survey zones","name":"Location_1","geometry":"fill","color":"var(--mon-stevens4-1)","where":"Location_1 = ''Taylor Creek Marsh''","fields":[{"field":"Strata","label":"Stratum"}]}]}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (17, N'Vegetation Type', 13, N'Maintain the existing species richness of the Region by providing for the perpetuation of the following plant associations:
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (18, N'Meadow and Wetland Vegetation', 13, N'Relative Abundance - Of the total amount of undisturbed vegetation in the Tahoe Basin: Maintain at least four percent meadow and wetland vegetation.', N'Vegetation types associated with meadows and wetlands (California Wildlife Habitat Relationship type “WTM” [wet meadow] and “PGS” [Perennial Grassland]) are queried and enumerated from the most recently available vegetation map (U.S. Forest Service - Remote Sensing Lab Pacific Southwest Region: TMU_Strata_07 [published 2009]). The Tahoe vegetation map is periodically updated with new satellite data (if available) and/or modelled and calibrated using field-based forest inventory and analysis data to assess the extent of different vegetation types and associated forest structure characteristics for the Region (USDA, 2009; Warbington et al., 2011).', 0, N'charts', N'{"measures":[{"title":"Meadow and wetland acres","sub":"Undisturbed and disturbed acres (2010), with the minimum of 4 percent of undisturbed vegetation (6,858 acres).","layer":91,"where":"TRPA_VegType IN (''Meadow'',''Wetland'')","x":"Development","xType":"category","xLabel":"Condition","y":"SUM_Acres","stat":"sum","seriesBy":"TRPA_VegType","seriesLabel":"Type","yLabel":"Acres","type":"stacked","standard":{"value":6857.5,"label":"Threshold minimum"}}]}', N'[{"Dashboard":"Threshold Dashboard","Label":"Relative Abundance of Meadows And Wetland Vegetation Types","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/77"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (19, N'Deciduous Riparian Vegetation', 13, N'Relative Abundance - Of the total amount of undisturbed vegetation in the Tahoe Basin: Maintain at least four percent deciduous riparian vegetation.', N'Vegetation types associated with deciduous riparian vegetation (montane riparian, aspen, and mix hardwood/conifer) were queried and enumerated from the most recently available vegetation map (U.S. Forest Service - Remote Sensing Lab Pacific Southwest Region: TMU_Strata_07 [published 2009]). The Tahoe vegetation map is periodically updated with new satellite data and/or modelled and calibrated using field-based forest inventory and analysis data to assess the extent of different vegetation types and associated forest structure characteristics for the Region (USDA, 2009; Warbington et al., 2011).', 0, N'charts', N'{"measures":[{"title":"Deciduous riparian acres","sub":"Undisturbed and disturbed acres by habitat type (2010), with the minimum of 4 percent of undisturbed vegetation (6,858 acres).","layer":91,"where":"TRPA_VegType = ''Deciduous Riparian''","x":"Development","xType":"category","xLabel":"Condition","y":"SUM_Acres","stat":"sum","seriesBy":"WHRTYPE","seriesLabel":"Habitat type","seriesNames":{"ADS":"Alpine dwarf shrub","MCP":"Montane chaparral","ASP":"Aspen","MHC":"Montane hardwood-conifer","MRI":"Montane riparian","PGS":"Perennial grassland","WTM":"Wet meadow","EPN":"Eastside pine","JPN":"Jeffrey pine","LPN":"Lodgepole pine","SMC":"Sierran mixed conifer","WFR":"White fir","RFR":"Red fir","JUN":"Juniper","SCN":"Subalpine conifer","BAR":"Barren","BBR":"Bitterbrush","LSG":"Low sage","SGB":"Sagebrush","LAC":"Lacustrine"},"yLabel":"Acres","type":"stacked","standard":{"value":6857.5,"label":"Threshold minimum"}}]}', N'[{"Dashboard":"Threshold Dashboard","Label":"Relative Abundance of Deciduous Riparian Vegetation","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/79"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (20, N'Shrub Abundance', 13, N'Relative Abundance - Of the total amount of undisturbed vegetation in the Tahoe Basin: Maintain no more than 25 percent dominant shrub association vegetation.', N'Updated vegetation maps were not available for this evaluation. Instead, the most recent data from 2009 is used. Periodically, the Tahoe vegetation map is updated with new satellite data (if available) and/or modeled and calibrated using field-based forest inventory and analysis data to assess the extent of different vegetation types and associated forest structure characteristics for the Region (USDA, 2009; Warbington et al., 2011). Vegetation types associated with shrubs were queried and enumerated from the most recently available vegetation map (U.S. Forest Service - Remote Sensing Lab Pacific Southwest Region: TMU_Strata_07 [published 2009]). As shown in Table 1 California Wildlife Habitat Relationship types were queried to represent shrub vegetation in this evaluation.', 0, N'charts', N'{"measures":[{"title":"Shrub acres","sub":"Undisturbed and disturbed acres by habitat type (2010), with the maximum of 25 percent of undisturbed vegetation (42,860 acres).","layer":91,"where":"TRPA_VegType = ''Shrub''","x":"Development","xType":"category","xLabel":"Condition","y":"SUM_Acres","stat":"sum","seriesBy":"WHRTYPE","seriesLabel":"Habitat type","seriesNames":{"ADS":"Alpine dwarf shrub","MCP":"Montane chaparral","ASP":"Aspen","MHC":"Montane hardwood-conifer","MRI":"Montane riparian","PGS":"Perennial grassland","WTM":"Wet meadow","EPN":"Eastside pine","JPN":"Jeffrey pine","LPN":"Lodgepole pine","SMC":"Sierran mixed conifer","WFR":"White fir","RFR":"Red fir","JUN":"Juniper","SCN":"Subalpine conifer","BAR":"Barren","BBR":"Bitterbrush","LSG":"Low sage","SGB":"Sagebrush","LAC":"Lacustrine"},"yLabel":"Acres","type":"stacked","standard":{"value":42859.5,"label":"Threshold maximum"}}]}', N'[{"Dashboard":"Threshold Dashboard","Label":"Relative Abundance of Shrub Vegetation Type","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/78"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9682, N'Stream Environment Zone Vegetation', 13, N'The non-degradation of stream environment zones (SEZs) management standard calls for the preservation of SEZ areas. SEZs serve critical roles in the Tahoe Region including natural water filtration, storage, and conveyance of surface runoff. SEZ encroachment reduces the potential to filter sediment and nutrients, and also reduces the capacity to treat surface runoff. Historic logging, grazing, and direct manipulation of stream channels have impacted the functions of wetlands, streams and surrounding riparian areas. The TRPA Code of Ordinances implements a land capability system that virtually eliminates new disturbance or development in riparian or wetland areas and provides incentives to relocate existing development from SEZs to higher capability land. Projects implemented through the Environmental Improvement Program have expanded the extent of riparian and wetland areas and improved their conditions.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9683, N'Native Vegetation and Land Capability', 13, N'The standard ensures that native vegetation is maintained consistent with the impervious coverage limits of the Bailey Land Capability Classification of the Lake Tahoe Region. Vegetation is integral to many scenic, wildlife, and recreational amenities in the Region. Vegetation also provides functional services including soil stabilization, nutrient cycling, surface water flow regulation, air purification, and noise control. The focus of vegetation preservation in the Region is to protect and maintain these and other attributes. The Bailey land capability system is implemented through the TRPA Code of Ordinances and regulates allowable coverage within land capability classes and has been in place and effective since 1987. At the parcel level, the application of the land capability system requires that areas not covered by impervious surfaces be left in a native or acceptably landscaped state.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (63, N'Stream Bioassessment and Physical Habitat', 13, N'TRPA began monitoring perennial streams in 2009 to determine if TRPA thresholds for stream habitat are being met, and to detect changes in the overall condition of the Tahoe Basin''s streams. Bioassessment, which uses benthic macroinvertebrates (BMI) and physical stream habitat to assess overall stream health, is used to monitor the Basin''s streams. To obtain a stream health "score", the California Stream Condition Index (CSCI) is used. The CSCI is a model that compares the BMI found in sampled streams against the BMI expected to be found in pristine streams in the Sierra Nevada.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (32, N'Stream Habitat Condition', 13, N'As indicated by the Stream Habitat Quality GIS data, amended May 1997, based upon the re-rated stream scores set forth in Appendix C-1 of the 1996 Evaluation Report, Maintain 105 miles of good stream habitat.', N'Streams are monitored using widely accepted bioassessment protocols established by the EPA and further refined by the California Department of Fish and Wildlife (CDFW) (Kaufmann et al. 1999; Ode 2007; Barbour et al. 1999). Specifically, stream monitoring is conducted using Standard Operating Procedures for Collecting Benthic Macroinvertebrate Samples and Associated Physical and Chemical Data for Ambient Bioassessments in California (Ode 2007). The TRPA stream monitoring program was developed in partnership with the EPA, CDFW, Nevada Department of Environmental Protection (NDEP), Lahontan Water Quality Control Board (Lahontan), and the U.S. Forest Service (USFS) (Fore 2007). Benthic macroinvertebrates (BMIs), as well as physical and chemical stream characteristics, are sampled at 48 streams annually.', 0, N'map', N'{"measures":[{"title":"Stream miles by rating","sub":"Miles of stream in each habitat condition rating, by rating year.","layer":32,"x":"Final_Rating","xType":"category","xLabel":"Rating","y":"Stream_Miles","stat":"sum","yLabel":"Stream miles","type":"bar","seriesBy":"Rating_Year","seriesLabel":"Rating year"},{"title":"Streams by condition class","sub":"Share of sampled streams in each CSCI condition class, by sampling period.","layer":83,"x":"Year","xType":"category","xLabel":"Period","y":"Value","yLabel":"Share of streams","format":".0%","type":"stacked","seriesBy":"Condition_Class","seriesLabel":"Condition class"}],"mapLayer":{"layer":32,"title":"Stream habitat condition","unit":"stream reach","unitPlural":"Stream reaches","name":"Assessment","colorBy":"Final_Rating","colorByLabel":"Rating","colors":{"A":"var(--mon-chlorophyll-6)","B":"var(--mon-chlorophyll-5)","C":"var(--mon-chlorophyll-3)","D":"var(--mon-chlorophyll-2)","Not Assessed":"var(--color-content-disabled)"},"pick":"Rating_Year","pickLabel":"Rating year","meta":[{"field":"Stream_Miles","suffix":" miles"}],"fields":[{"field":"Final_Rating","label":"Rating"},{"field":"Stream_Condition","label":"Condition"},{"field":"Stream_Miles","label":"Miles"},{"field":"Ownership","label":"Owner"}]}}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (27, N'Fish Habitat Mapping', 13, N'A non-degradation standard shall apply to fish habitat in Lake Tahoe. Achieve the equivalent of 5,948 total acres of excellent habitat as indicated by the Prime Fish Habitat GIS Layer as may be amended based on best available science.', N'The monitoring approach used for evaluating the attainment status of this standard involves the mapping and classification of fish habitats in the nearshore (the lake zone that exists approximately between elevations of 6,229 to 6,199). In 1971, a cooperative survey was done by various state and federal fish and wildlife agencies to identify fish and aquatic habitats of special significance. This work produced a Prime Fish Habitat Map that TRPA adopted in 1984. This map, as amended in 1997, is still the map TRPA uses today. Byron et al. (1989) as part of their fish habitat study resurveyed and mapped fish habitat around Lake Tahoe. According to TRPA (1996), the Byron et al. work represented a more accurate picture of the types of fish habitat based on lakebed substrate. The 2006 and 2011 Threshold Evaluations Reports utilized an updated fish habitat map based on satellite imagery collected in 2002 (Metz and Herold 2004; Herold, Metz, and Romsos 2007a).', 0, N'charts', N'{"measures":[{"title":"Lake Tahoe fish habitat by type","sub":"Acres of nearshore fish habitat by type, from 2015 mapping. Feed and cover plus spawning habitat count as excellent habitat; the standard is 5,948 acres.","layer":104,"x":"Habitat2015","xType":"category","xLabel":"Habitat type","xNames":{"1":"Marginal","2":"Feed and cover","3":"Spawning"},"y":"Acres","stat":"sum","yName":"Acres","yLabel":"Acres","type":"bar"},{"title":"Lakebed substrate","sub":"Acres of each lakebed substrate type in the nearshore, from 2015 mapping.","layer":104,"x":"Substrate2015","xType":"category","xLabel":"Substrate","xNames":{"1":"Sand","2":"Cobble","3":"Boulder","4":"Sand, cobble, and boulder","5":"Gravel to large boulder","6":"Cobble, boulder, and bedrock","7":"Periphyton","11":"Gravel","13":"Gravel to small boulder"},"y":"Acres","stat":"sum","yLabel":"Acres","type":"bar","orientation":"h","sort":"desc"}]}', N'[{"Dashboard":"Threshold Dashboard","Label":"Acres of \"Prime\" Fish Habitat","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/24"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (74, N'Lahontan Cutthroat Trout Recovery', 13, N'Two populations of Lahontan Cutthroat Trout are actively monitored in the Tahoe Basin. The fluvial population in the Upper Truckee River in the Meiss Meadows area is actively managed and monitored by the USDA Forest Service. The lacustrine population in Fallen Leaf Lake is actively managed and monitored by the US Fish and Wildlife Service.', N'Two populations of Lahontan Cutthroat Trout are actively monitored in the Tahoe Basin. The fluvial population in the Upper Truckee River in the Meiss Meadows area is actively managed and monitored by the USDA Forest Service. The lacustrine population in Fallen Leaf Lake is actively managed and monitored by the US Fish and Wildlife Service.', 0, N'context', NULL, NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9621, N'Instream Flow', 13, N'This indicator measures whether streamflows have been altered by diversions. Alteration of streamflow regimes, such as water diversions, can result in adverse impacts to stream habitat diversity, function, and productivity of aquatic ecosystems and organisms. Past streamflow diversions exist in the Tahoe Region for a variety of reasons including providing water for agriculture and sending water to communities outside the Tahoe Region. Regional policies are aimed at removing existing streamflow diversions and prohibiting new diversions. There is no active monitoring of streamflow diversions but new streamflow diversions are not permitted.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9622, N'Stream Intakes Diverted to Lake Sources', 13, N'This standard was retired on April 24, 2019. See the Governing Board staff report at https://www.trpa.gov/wp-content/uploads/documents/archive/CC-7-Thresholds-2019_4_24_GB_TPMI.pdf for more information. The content on this page is archived and available for evaluations prior to April 2019, but will not be updated or maintained for future evaluations.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (2, N'Osprey', 13, NULL, N'A shoreline survey is conducted by boat monthly during spring and summer months following standard protocols. Additional surveys are conducted at historic and likely nest sites at other lakes and upland areas. All suitable nesting habitat is surveyed for nest activity and nest success.', 0, N'charts', N'{"measures":[{"title":"Active osprey nests","sub":"Active nests counted each year, with the threshold.","layer":96,"where":"Wildlife_Species = ''Osprey''","x":"Year","y":"Total","yName":"Active nests","yLabel":"Active nests","type":"bar","span":"span-12","standard":{"field":"Threshold_Value"}}],"mapLayer":{"service":"https://maps.trpa.org/server/rest/services/Wildlife_Activity/MapServer","layer":3,"title":"Osprey nest buffers","unit":"nest","unitPlural":"Nests","name":"NEST_ID","countAsSites":false,"colorBy":"NEST_STATUS","colorByLabel":"Nest status","colors":{"Active, Successful":"var(--mon-stevens4-2)","Active, Not Successful":"var(--mon-stevens4-3)","Not Active, Not Successful":"var(--mon-stevens4-1)","Nest Gone":"var(--mon-stevens4-4)"},"pick":"Year","pickLabel":"Survey year","fields":[{"field":"NEST_STATUS","label":"Status"},{"field":"Year","label":"Year"}]}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Osprey Population Sites","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/158"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (4, N'Nesting Bald Eagle', 13, NULL, N'Known nest sites are visited regularly during the incubation and fledging periods to determine reproductive success. Monthly boat surveys during non-winter months are conducted to identify any new nest sites surrounding Lake Tahoe, and ad-hoc surveys are conducted in other areas in support of environmental assessments for proposed projects.', 0, N'charts', N'{"measures":[{"title":"Active bald eagle nests","sub":"Active nests counted each year, with the threshold.","layer":96,"where":"Wildlife_Species = ''Bald Eagle - nesting''","x":"Year","y":"Total","yName":"Active nests","yLabel":"Active nests","type":"bar","standard":{"field":"Threshold_Value"}},{"title":"Wintering bald eagles","sub":"Individuals counted each year.","layer":96,"where":"Wildlife_Species = ''Bald Eagle - winter''","x":"Year","y":"Total","yName":"Individuals","yLabel":"Individuals","type":"bar"}],"mapLayer":{"service":"https://maps.trpa.org/server/rest/services/Wildlife_Activity/MapServer","layer":0,"title":"Bald eagle nest buffers","unit":"nest","unitPlural":"Nests","name":"Nest_Name","countAsSites":false,"meta":[{"field":"Years_Active"}],"fields":[{"field":"Years_Active","label":"Years active"},{"field":"Years_Reproductive","label":"Years reproductive"}]}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Nesting Bald Eagle Population Sites","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/160"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (3, N'Wintering Bald Eagle', 13, N'Provide a minimum of 2 Bald Eagle (Winter) population sites.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (5, N'Golden Eagle', 13, N'Provide a minimum of 4 Golden Eagle population sites.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (6, N'Peregrine Falcon', 13, NULL, N'Biologists observe historic or potential nest sites for a minimum of four hours per month, April through August following standard U.S. Forest Service protocol. All potential nesting habitat is surveyed and incidental sighting are used to help focus monitoring efforts.', 0, N'charts', N'{"measures":[{"title":"Active peregrine falcon nests","sub":"Active nests counted each year, with the threshold.","layer":96,"where":"Wildlife_Species = ''Peregrine Falcon''","x":"Year","y":"Total","yName":"Active nests","yLabel":"Active nests","type":"bar","span":"span-12","standard":{"field":"Threshold_Value"}}],"mapLayer":{"service":"https://maps.trpa.org/server/rest/services/Wildlife_Activity/MapServer","layer":2,"title":"Peregrine falcon nest buffers","unit":"nest","unitPlural":"Nests","name":"SITE_NAME","countAsSites":false,"meta":[{"field":"Years_Used"}],"fields":[{"field":"Years_Used","label":"Years used"}]}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Peregrine Falcon Population Sites","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/162"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (29, N'Northern Goshawk', 13, NULL, N'Portions of known and potential northern goshawk habitat are surveyed following well-accepted protocols including a combination of dawn acoustic surveys, stand search surveys, and broadcast surveys. Recent survey work has been conducted in response to proposed projects and has been primarily focused at assessment of project level impacts, not assessment of population status and trends in the Tahoe Basin. The last full population survey was completed in 2010.', 0, N'charts', N'{"measures":[{"title":"Reproductively active goshawk territories","sub":"Active territories counted each year, with the threshold.","layer":96,"where":"Wildlife_Species = ''Northern Goshawk''","x":"Year","y":"Total","yName":"Active territories","yLabel":"Active territories","type":"bar","span":"span-12","standard":{"field":"Threshold_Value"}}],"mapLayer":{"service":"https://maps.trpa.org/server/rest/services/Wildlife_Habitat/MapServer","layer":0,"title":"Goshawk threshold zones","unit":"territory","unitPlural":"Territories","name":"Territory","countAsSites":false,"meta":[{"field":"Acres","suffix":" acres"}],"fields":[{"field":"Acres","label":"Acres"}]}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Northern Goshawk Population Sites","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/157"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (7, N'Waterfowl', 13, NULL, N'The methodologies and indicators used by TRPA to evaluate the attainment status of the waterfowl standard has varied over time. The 2001 Threshold Evaluation Report used observed bird species richness and diversity along with the human activity rating system to gage threshold standard attainment status (TRPA 2001). The 2006 Threshold Evaluation Report used observation of bird species richness and diversity as well as an assessment of detrimental or non-native species, but did not use the human disturbance rating system that was used in 2001. The 2011 Threshold Evaluation Report used only a human disturbance rating system as a means to measure status (TRPA 2012a). Since 2015, the assessment method used is based on field observations and human activity levels at mapped waterfowl population sites, similar to the 2011 Threshold Evaluation Report methods. No formal waterfowl surveys were conducted. Each site was visited by a qualified observor to conduct the human disturbance rating evaluation.', 0, N'charts', N'{"measures":[{"title":"Average human activity rating","sub":"Average human activity rating score across waterfowl sites, by survey year.","layer":96,"where":"Wildlife_Species = ''Waterfowl''","x":"Year","y":"Total","yName":"Average rating","yLabel":"Human activity rating","type":"bar"},{"title":"Human activity rating by site","sub":"Human activity rating at each waterfowl site, by survey year. Choose a site.","layer":94,"x":"Year","y":"value","unpivot":{"prefix":"F"},"yName":"Rating","yLabel":"Human activity rating","type":"bar","pick":"Name","pickLabel":"Site"}],"mapLayer":{"service":"https://maps.trpa.org/server/rest/services/Wildlife_Habitat/MapServer","layer":2,"title":"Waterfowl habitat","unit":"site","unitPlural":"Sites","name":"NAME","countAsSites":false,"fields":[{"field":"NAME","label":"Site"}]}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Waterfowl Population Sites","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/166"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9765, N'Deer Disturbance-Free Zone', 13, N'Mule deer (Odocoileus hemionus) are of exceptional value to the ecosystem and to the public for wildlife viewing and hunting. Portions of deer from the Verdi sub-unit of the Loyalton-Truckee herd, approaching from the north and west, and the Carson River herd, approaching from the east, can be found in the Tahoe Region during the summer and typically migrate to lower elevation areas with less snow for the winter. Disturbance-free zones protect important areas that are used by certain species by restricting habitat manipulations or other activities that would degrade the condition of the habitat within the zone. These zones can be affected by construction and recreational or commercial uses including biking and off-road vehicle use. While TRPA does not permit projects that would reduce the availability of fawning habitat, populations are mostly affected by the loss of wintering habitat outside the region (Ungulate migrations of the western United States, Volume 1 (ver. 1.1, December 2023)).
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9756, N'Riparian Habitat', 13, N'This indicator has been retired and is no longer reported. This standard was retired on May 23, 2018, as part of the Threshold Update Initiative: Reorganization and Non-Policy Technical Corrections. See the Governing Board staff report at https://www.trpa.gov/wp-content/uploads/documents/archive/May-23-2018-Governing-Board-Packet-Final.pdf for more information. The content on this page is archived and available for evaluations prior to May 2018, but will not be updated or maintained for future evaluations.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9901, N'Population', 14, N'The Lake Tahoe Region had 55,836 residents at the 2020 census. Population peaked at 62,843 in 2000; over the 30 years from 1990 to 2020 it grew 6 percent, while the five surrounding counties grew 92 percent, Nevada 138 percent, and California 33 percent.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9902, N'Age', 14, N'The Basin''s residents have grown older over three decades and are now slightly older than those of nearby counties and urban areas. The baby boom generation shows in the age profile: the largest age group was 30 to 40 in 1990, 40 to 50 in 2000, and 60 to 70 by 2020.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9903, N'Race and Ethnicity', 14, N'The Basin''s population has grown more diverse since the 2000 census. The share of residents who identify as Hispanic or Latino rose from 18 percent in 2000 to 22 percent in 2020, and Black, Indigenous, and other people of color made up about 31 percent of residents in 2020, up from 24 percent in 2000.', N'Figures come from the U.S. Census Bureau''s decennial census and American Community Survey (ACS) 5-year estimates, queried through the Census Bureau''s API and summarized for the Tahoe Region by TRPA. Decennial counts are a full count every 10 years; ACS estimates are yearly averages of five years of samples, so they move more smoothly and carry a margin of error.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9911, N'Greenhouse Gas Emissions', 15, N'Greenhouse gases such as carbon dioxide and methane trap heat in the atmosphere and drive climate change. In the Tahoe Region most emissions come from heating and powering buildings and from driving.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9912, N'Air Quality and Wildfire Smoke', 15, N'Wildfire smoke now brings the Tahoe Region its worst air of the year. Fine particles in smoke reach deep into the lungs, and smoke days are expected to grow as fire seasons lengthen.', N'A network of low-cost PurpleAir sensors around the Basin measures fine particulate matter (PM2.5) continuously. Readings from sensors that pass quality checks are averaged each day and converted to the U.S. Environmental Protection Agency''s Air Quality Index. Values above 100 are unhealthy for sensitive groups.', 0, N'charts', N'{"measures":[{"title":"Daily air quality index","sub":"Daily mean Air Quality Index from PurpleAir sensors in the Basin, 2017 to 2024.","json":"data/climate/air-quality-index.json","sourceHref":"https://trpa-agency.github.io/ClimateResilienceDashboard/html/1.2.a_Purple_Air_v2.html","sourceLabel":"Climate Resilience Dashboard","x":"Date","xType":"date","xLabel":"Date","y":"Air quality index","yName":"Air quality index","yLabel":"Air quality index","type":"line","span":"span-12","standard":{"value":100,"label":"Unhealthy for sensitive groups"}}]}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Air Quality and Extreme Heat","Url":"https://climate.laketahoeinfo.org/air-quality-and-extreme-heat"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9913, N'Lake Level', 15, N'Lake Tahoe''s surface rises with snowmelt and falls through dry years. Below the natural rim, 6,223 feet, no water flows out into the Truckee River. Above it, the dam at Tahoe City holds the lake no higher than the legal limit of 6,229.1 feet.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9914, N'Lake Surface Temperature', 15, N'Lake Tahoe''s surface water has warmed over the last half century. Warmer water mixes less often, holds less oxygen at depth, and favors algae and warm-water invasive species.', N'A buoy at mid-lake records the surface temperature through the year. The chart shows the daily mean in degrees Fahrenheit for the most recent year published.', 0, N'charts', N'{"measures":[{"title":"Mid-lake surface temperature","sub":"Daily mean surface temperature at mid-lake, degrees Fahrenheit, January 2024 to January 2025.","json":"data/climate/lake-temperature.json","sourceHref":"https://trpa-agency.github.io/ClimateResilienceDashboard/html/1.3.b_Lake_Temp.html","sourceLabel":"Climate Resilience Dashboard","x":"Date","xType":"date","xLabel":"Date","y":"Temperature","yName":"Surface temperature","yLabel":"Degrees Fahrenheit","type":"line","zero":false,"span":"span-12"}]}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Lake Conditions","Url":"https://climate.laketahoeinfo.org/lake-conditions"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9915, N'Precipitation and Snow', 15, N'Most of the Tahoe Region''s water arrives as winter snow, which melts slowly into streams and the lake through spring and summer. As the climate warms, more of it falls as rain, runs off sooner, and leaves less snowpack for the dry season.', N'The Central Sierra Snow Laboratory near Donner Pass, just outside the Basin, has a daily record of precipitation and snowfall from 1970. Totals here are by calendar year. The share falling as snow comes from the same record.', 0, N'charts', N'{"measures":[{"title":"Share of precipitation as snow and rain","sub":"Percent of each year''s precipitation that fell as snow and as rain, 1987 to 2019.","json":"data/climate/snow-and-rain.json","sourceHref":"https://trpa-agency.github.io/ClimateResilienceDashboard/html/1.3.d_Precip.html","sourceLabel":"Climate Resilience Dashboard","x":"Year","xLabel":"Year","y":"Percent","seriesBy":"Form","seriesLabel":"Falls as","seriesOrder":["Snow","Rain"],"seriesColors":{"Snow":"var(--mon-turbid-2)","Rain":"var(--mon-turbid-6)"},"yLabel":"Percent","type":"stacked","span":"span-12"},{"title":"Total precipitation","sub":"Millimeters of precipitation, rain and the water in snow, by calendar year, 1970 to 2019.","service":"https://maps.trpa.org/server/rest/services/LTinfo_Climate_Resilience_Dashboard/MapServer","layer":145,"x":"Year","xLabel":"Year","y":"Full_Day_Total_Precip_mm","stat":"sum","yName":"Precipitation","yLabel":"Millimeters","type":"bar"},{"title":"New snowfall","sub":"Centimeters of new snow, by calendar year, 1970 to 2019.","service":"https://maps.trpa.org/server/rest/services/LTinfo_Climate_Resilience_Dashboard/MapServer","layer":145,"x":"Year","xLabel":"Year","y":"New_Snow_cm","stat":"sum","yName":"New snow","yLabel":"Centimeters","type":"bar"}]}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Precipitation and Extreme Storms","Url":"https://climate.laketahoeinfo.org/precipitation-and-extreme-storms"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9916, N'Renewable Energy', 15, N'Electricity generation is one of the Region''s largest sources of greenhouse gas emissions. Shifting the power supply to solar, wind, geothermal, and hydropower lowers emissions without asking residents to use less.', N'Liberty Utilities serves the California side of the Basin and NV Energy the Nevada side. Each reports the share of its power mix from renewable sources each year.', 0, N'charts', N'{"measures":[{"title":"Electricity from renewable sources","sub":"Share of each utility''s power mix from renewable and non-renewable sources.","service":"https://maps.trpa.org/server/rest/services/LTinfo_Climate_Resilience_Dashboard/MapServer","layer":144,"x":"Year","xLabel":"Year","y":"Share","stat":"sum","seriesBy":"Type","seriesLabel":"Source","seriesOrder":["Renewables","Non-Renewable"],"seriesNames":{"Renewables":"Renewable","Non-Renewable":"Non-renewable"},"pick":"Source","pickLabel":"Utility","format":".0%","yLabel":"Share of power mix","type":"stacked","span":"span-12"}]}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Renewable Energy","Url":"https://climate.laketahoeinfo.org/renewable-energy"},{"Dashboard":"Climate Resilience Dashboard","Label":"Access to Housing","Url":"https://climate.laketahoeinfo.org/access-to-housing"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9904, N'Housing', 16, N'Over four decades, homes occupied by full-time residents have held at slightly under half of all housing in the Basin, except in 2000, when they rose to 55 percent. Seasonal, recreational, or occasional use accounted for almost half of all housing in 2020.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9905, N'Income', 16, N'Household incomes in the Basin have generally risen over the past decade, with a notable rise from 2019 to 2021, the latest years with census estimates. In the Washoe County part of the Basin, median income adjusted for inflation rose 29 percent from 2019 to 2021, while elsewhere in the Basin it held roughly steady.', N'Figures come from the U.S. Census Bureau''s decennial census and American Community Survey (ACS) 5-year estimates, queried through the Census Bureau''s API and summarized for the Tahoe Region by TRPA. Decennial counts are a full count every 10 years; ACS estimates are yearly averages of five years of samples, so they move more smoothly and carry a margin of error.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9921, N'Deed-Restricted Housing', 16, N'A deed restriction keeps a home affordable, or reserved for people who work in the Region, for as long as the restriction is recorded. TRPA grants development bonuses and other incentives for housing that carries one.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9922, N'Home Prices and Rents', 16, N'Home prices in the Tahoe Region have risen far faster than local wages, and many homes sell as second homes or vacation rentals. The gap pushes people who work here to live outside the Basin and commute in.', N'Home sale prices are the average of each month''s mean residential sale price in the Basin. Rents are the asking rent per unit in multifamily buildings, by quarter, from a commercial rental market survey.', 0, N'charts', N'{"measures":[{"title":"Average home sale price","sub":"Mean of the monthly average residential sale price, by year, dollars.","service":"https://maps.trpa.org/server/rest/services/LTinfo_Climate_Resilience_Dashboard/MapServer","layer":147,"x":"year","xLabel":"Year","y":"Purchase_Amt","stat":"avg","yName":"Average sale price","yLabel":"Dollars","type":"bar"},{"title":"Asking rent per unit","sub":"Average monthly asking rent per multifamily unit, by quarter, dollars.","service":"https://maps.trpa.org/server/rest/services/LTinfo_Climate_Resilience_Dashboard/MapServer","layer":146,"x":"Period","xType":"category","xLabel":"Quarter","y":"Asking_Rent_Per_Unit","yName":"Asking rent","yLabel":"Dollars a month","type":"line","zero":false}]}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Demographics and Workforce","Url":"https://climate.laketahoeinfo.org/demographics-and-workforce"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9924, N'Transient Occupancy Tax', 16, N'Transient occupancy tax is charged on hotel, motel, and short-term rental stays. Its revenue tracks the visitor economy the Region depends on, and how it shifts with snow years, fire seasons, and the economy.', N'Each local jurisdiction reports the tax collected in each fiscal year, July through June. El Dorado County''s collections are not in the fiscal-year record, so the totals cover the other four jurisdictions.', 0, N'charts', N'{"measures":[{"title":"Transient occupancy tax collected","sub":"Dollars collected each fiscal year, by jurisdiction.","service":"https://maps.trpa.org/server/rest/services/LTinfo_Climate_Resilience_Dashboard/MapServer","layer":137,"where":"Duration = ''FY''","x":"Fiscal_Year","xType":"category","xLabel":"Fiscal year","y":"TOT_Collected","stat":"sum","seriesBy":"Jurisdiction","seriesLabel":"Jurisdiction","yLabel":"Dollars","type":"stacked","span":"span-12"}]}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Economic Resilience","Url":"https://climate.laketahoeinfo.org/economic-resilience"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9925, N'Jobs and Wages', 16, N'Steady, well-paid jobs let people who work in the Region afford to live here. Tahoe''s economy leans on seasonal tourism and recreation, which keeps many jobs part-year and many wages low.', N'The U.S. Census Bureau''s Longitudinal Employer-Household Dynamics program counts jobs by work location each year from unemployment insurance records, in three monthly earnings bands. The 2022 count is about double 2021, which looks like a processing error, so the chart ends at 2021.', 0, N'charts', N'{"measures":[{"title":"Jobs in the Basin by monthly earnings","sub":"Jobs located in the Basin each year, by monthly earnings band, 2002 to 2021.","service":"https://maps.trpa.org/server/rest/services/LTinfo_Climate_Resilience_Dashboard/MapServer","layer":142,"where":"Year <= 2021","x":"Year","xLabel":"Year","y":[{"field":"CE01","name":"$1,250 or less"},{"field":"CE02","name":"$1,251 to $3,333"},{"field":"CE03","name":"More than $3,333"}],"stat":"sum","yLabel":"Jobs","type":"stacked","span":"span-12"}]}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Economic Resilience","Url":"https://climate.laketahoeinfo.org/economic-resilience"},{"Dashboard":"Climate Resilience Dashboard","Label":"Demographics and Workforce","Url":"https://climate.laketahoeinfo.org/demographics-and-workforce"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (14, N'Aquatic Invasive Plants', 17, NULL, N'Monthly veliger surveys for mussel larvae are done during the boating season.', 0, N'map', N'{"measures":[{"title":"Invasive plant acres by location","sub":"Acres of Eurasian watermilfoil and curlyleaf pondweed at each location.","layer":95,"x":"Location","xType":"category","xLabel":"Location","y":[{"field":"Eurasian_Watermilfoil","name":"Eurasian watermilfoil"},{"field":"Curlyleaf_Pondweed","name":"Curlyleaf pondweed"}],"yLabel":"Acres","type":"stacked","orientation":"h","sort":"desc","span":"span-12"},{"title":"Control sites by status","sub":"Aquatic invasive plant control sites by threshold status in 2023.","layer":114,"x":"Threshold_Status_2023","xType":"category","xLabel":"Status","y":"OBJECTID","stat":"count","yName":"Sites","yLabel":"Sites","type":"bar"},{"title":"Control sites by infestation status","sub":"Aquatic invasive plant control sites by infestation status code in 2024.","layer":114,"x":"Infest_Status_2024","xType":"category","xLabel":"Infestation status (2024)","y":"OBJECTID","stat":"count","yName":"Sites","yLabel":"Sites","type":"bar"}],"sitesLayer":{"layer":114,"name":"Site_Name","status":"Threshold_Status_2023"},"siteProfile":{"facts":[{"label":"Notes","field":"Info"}],"section":{"type":"statusStrip","title":"Infestation status and control","years":[2018,2019,2020,2021,2022,2023,2024],"status":"Infest_Status_","actions":"Contr_","phases":{"C":"Control","P":"Planning","S":"Surveillance"}}}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Aquatic Invasive Species Prevention","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/102"},{"Dashboard":"Climate Resilience Dashboard","Label":"Aquatic Invasive Species","Url":"https://climate.laketahoeinfo.org/aquatic-invasive-species"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9093, N'Watercraft Inspections', 17, N'Watercraft inspected for aquatic invasive species before launching at Lake Tahoe each year, how many needed decontamination, and where the inspection stations are.', NULL, 0, N'charts', N'{"measures":[{"title":"Watercraft inspected","sub":"Watercraft inspected each year, by whether they needed decontamination.","layer":93,"x":"Year","y":[{"field":"Watercraft_Decontaminated","name":"Decontaminated"},{"field":"No_Decontamination_Necessary","name":"No decontamination needed"}],"yLabel":"Watercraft","type":"stacked","span":"span-12"}],"sitesLayer":{"layer":103,"name":"STATION_NAME","status":"STATION_TYPE","unit":"station"}}', N'[{"Dashboard":"Climate Resilience Dashboard","Label":"Aquatic Invasive Species","Url":"https://climate.laketahoeinfo.org/aquatic-invasive-species"}]');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (78, N'Aquatic Plant Survey Zones', 17, N'The Aquatic Plant Monitoring Program (APMP) is intended to gather, analyze, and report information relative to aquatic plant populations in Lake Tahoe, with an emphasis on collecting data that can be used to guide control efforts for aquatic invasive plant', N'Two levels of aquatic plant survey effort (spatial design) are applied to the APMP and each is performed on a different temporal scale. Once every five years a nearshore-wide aquatic plant survey is conducted via interpretation and mapping of remotely sensed data in combination with in situ diver sampling. Annually, only an in situ diver survey (or a reasonable surrogate) is performed following targeted and a stratified systematic sampling of transect lines with incorporated quadrats. The nearshore-wide aquatic plant survey (i.e., the combination of remote sensing imagery analysis with diver surveys) attempts to provide for a “baseline” status quantification of all aquatic plant beds around Lake Tahoe’s nearshore zone. The transect surveys allows for training and validation of remotely sensed data, and annual surveillance to establish trend information and the detection of new infestations of aquatic invasive plants. The sampling frame (i.e., survey area) and habitat stratification scheme used for line-transect surveys conducted in intervening years will be the same as that used for the nearshore-wide survey. Four habitat strata are used to divide the aquatic plant population into meaningful sampling units, including open-water nearshore, marshes, major tributaries, and marinas and embayments.', 0, N'map', N'{"measures":[{"title":"Survey zone acres by stratum","sub":"Acres of aquatic vegetation survey zones in each stratum.","layer":42,"x":"Strata","xType":"category","xLabel":"Stratum","y":"Acres","stat":"sum","yName":"Acres","yLabel":"Acres","type":"bar"},{"title":"Survey zones by stratum","sub":"Number of aquatic vegetation survey zones in each stratum.","layer":42,"x":"Strata","xType":"category","xLabel":"Stratum","y":"OBJECTID","stat":"count","yName":"Survey zones","yLabel":"Survey zones","type":"bar"}],"mapLayer":{"layer":42,"title":"Aquatic vegetation survey zones","unit":"survey zone","unitPlural":"Survey zones","name":"Location_1","colorBy":"Strata","colorByLabel":"Stratum","colors":{"Marina/Embayment":"#3e72b0","Nearshore Open Water":"#5a9cb0","Marsh":"#89bf40","Mrash":"#89bf40","Stream":"#e49937"},"labels":{"Mrash":"Marsh (recorded as Mrash)"},"meta":[{"field":"Strata"},{"field":"Acres","suffix":" acres"}],"fields":[{"field":"Strata","label":"Stratum"},{"field":"Acres","label":"Acres"},{"field":"Orient","label":"Orientation"}]}}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9034, N'Submerged Aquatic Vegetation', 17, N'Mapped patches of targeted submerged aquatic vegetation in Lake Tahoe.', NULL, 0, N'map', N'{"mapLayer":{"layer":34,"title":"Targeted submerged aquatic vegetation","unit":"vegetation patch","unitPlural":"Vegetation patches","list":false,"countAsSites":false,"fields":[{"field":"Type","label":"Type"}]}}', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9786, N'No Active Aquatic Invasive Plant Infestations', 17, N'Aquatic invasive species (AIS) are non-native organisms that threaten the abundance and diversity of native organisms in Lake Tahoe. Controlling and eradicating AIS in the Lake Tahoe Region is a top priority of the Lake Tahoe Environmental Improvement Program (EIP). The standard establishes the goal that all aquatic invasive plant infestations in Lake Tahoe be in the surveillance management category.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig, RelatedLinks) VALUES (9787, N'Aquatic Invasive Plants in the Tahoe Keys', 17, N'Aquatic Invasive Species (AIS) are non-native organisms that threaten the abundance and diversity of native organisms in Lake Tahoe. The Tahoe Keys is the largest and most persistent population of aquatic weeds growing in the region, infesting over 172 acres of waterways. All other lake-wide infestations combined account for approximately 20 acres. The 2015 Lake Tahoe Aquatic Invasive Species Implementation Plan lists the Tahoe Keys lagoons as the highest priority areas for control of AIS in Lake Tahoe.
