PABILITY IN (''1A'',''1B'',''1C'',''2'',''3'',''4'',''5'',''6'',''7'')","title":"Land capability (Bailey 1974)","unit":"land capability area","unitPlural":"Land capability areas","name":"CAPABILITY","list":false,"countAsSites":false,"colorBy":"CAPABILITY","colorByLabel":"Land capability district","colors":{"1A":"#d1ff73","1B":"#ffff00","1C":"#4ce600","2":"#4c7300","3":"#0084a8","4":"#ffd37f","5":"#ffaa00","6":"#cd8966","7":"#734c00"},"labels":{"1A":"District 1A","1B":"District 1B","1C":"District 1C","2":"District 2","3":"District 3","4":"District 4","5":"District 5","6":"District 6","7":"District 7"},"fields":[{"field":"CAPABILITY","label":"Land capability district"},{"field":"PERCENT_COVERAGE_ALLOWED","label":"Coverage allowed (share)"},{"field":"Acres","label":"Acres"}]}}', N'[{"Dashboard":"Threshold Dashboard","Label":"Percent of Land Coverage Within Land Capability Class 1a (allow up to 1% impervious coverage)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/61"},{"Dashboard":"Threshold Dashboard","Label":"Percent of Land Coverage Within Land Capability Class 1b (allow up to 1% impervious coverage)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/62"},{"Dashboard":"Threshold Dashboard","Label":"Percent of Land Coverage Within Land Capability Class 1c (allow up to 1% impervious coverage)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/63"},{"Dashboard":"Threshold Dashboard","Label":"Percent of Land Coverage Within Land Capability Class 2 (allow up to 1% impervious coverage)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/64"},{"Dashboard":"Threshold Dashboard","Label":"Percent of Land Coverage Within Land Capability Class 3 (allow up to 5% impervious coverage)","Url":"https://thresholds.laketahoeinfo.org/threshold/indicators/65"},{"Dashboard":"Threshold Dashboard","Label":"Percent of Land Coverage Within Land Capability Class 4 (allow up to 20% impervious coverage)","Url":"https://thresholds.la